/* =====================================================================
   Programme — Spécialité physique-chimie, classe de Première générale
   Partie « L'énergie : conversions et transferts »
   ===================================================================== */
window.COURS = (window.COURS || []).concat([

/* ========= 9. ÉNERGIE ET PUISSANCE ÉLECTRIQUES ========= */
{
id:"electrique", n:10, titre:"Énergie et puissance électriques",
sous:"Ce que consomme un appareil, et ce qu'il en fait",
desc:"Puissance, énergie, loi d'Ohm, effet Joule, bilan de puissance et rendement.",
duree:35,
sections:[
 {titre:"Puissance et énergie : deux mots, deux idées", blocs:[
  {t:"idee", x:"La **puissance** dit à quelle vitesse l'énergie est transférée. L'**énergie** dit combien a été transféré en tout. Confondre les deux est l'erreur la plus répandue de ce chapitre."},
  {t:"p", x:"Une comparaison qui règle la question une fois pour toutes : la puissance est le **débit du robinet**, l'énergie est le **volume dans le seau**. Un gros robinet ouvert une seconde peut remplir moins qu'un filet d'eau ouvert une heure. De même, un four très puissant allumé deux minutes consomme moins qu'une ampoule faible restée allumée toute la nuit."},
  {t:"formule", titre:"La relation entre les deux",
   x:"$E = P × Δt$",
   note:"$E$ en @u{J} (joules) · $P$ en @u{W} (watts) · $Δt$ en **secondes**. Un watt, c'est un joule par seconde."},
  {t:"piege", titre:"Le temps se compte en secondes", x:"Dans $E = P × Δt$, la durée doit être en **secondes** pour obtenir des joules. $30$ minutes valent $1800$ @u{s}, une heure vaut $3600$ @u{s}. Laisser des minutes donne un résultat 60 fois trop petit."},
  {t:"formule", titre:"L'unité des factures : le kilowattheure",
   x:"$1$ @u{kWh} $= 1000$ @u{W} $× 3600$ @u{s} $= 3{,}6 × 10^{6}$ @u{J}",
   note:"C'est l'énergie consommée par un appareil de $1000$ @u{W} pendant une heure."},
  {t:"p", x:"Le kilowattheure a mauvaise réputation auprès des élèves, mais il est très logique : c'est simplement une puissance multipliée par une durée, avec des unités pratiques plutôt que des joules. Une plaque de $2000$ @u{W} utilisée pendant une demi-heure consomme $2 × 0{,}5 = 1$ @u{kWh}."}
  ,{t:"mots", items:[
   ["Tension ($U$, en @u{V})","La « poussée » électrique entre deux points. Elle se mesure aux **bornes** d'un dipôle, avec un voltmètre branché en dérivation."],
   ["Intensité ($I$, en @u{A})","Le débit de charges qui traversent le circuit. Elle se mesure **dans** le circuit, avec un ampèremètre branché en série."],
   ["Résistance ($R$, en @u{Ω})","La difficulté qu'un dipôle oppose au passage du courant."],
   ["Puissance ($P$, en @u{W})","La vitesse à laquelle l'énergie est transférée. C'est le débit du robinet."],
   ["Énergie ($E$, en @u{J})","La quantité totale transférée. C'est le volume dans le seau."],
   ["Effet Joule","L'échauffement inévitable d'un conducteur parcouru par un courant."],
   ["Rendement ($η$)","La part de l'énergie reçue qui sert vraiment à ce qu'on demande. Toujours inférieur à 1."]
  ]},
  {t:"check", q:"Un radiateur de $1500$ @u{W} fonctionne pendant $2$ heures. Quelle énergie a-t-il consommée, en @u{kWh} ?",
   choix:["$3$ @u{kWh}","$3000$ @u{kWh}","$750$ @u{kWh}","$1500$ @u{kWh}"], bonne:0,
   expl:["Exact : $1500$ @u{W} $= 1{,}5$ @u{kW}, et $1{,}5 × 2 = 3$ @u{kWh}.",
         "Tu as multiplié en watts sans convertir en kilowatts. Un kilowatt vaut $1000$ @u{W} : il faut diviser par 1000.",
         "Tu as divisé par la durée au lieu de multiplier. Plus l'appareil fonctionne longtemps, plus il consomme.",
         "C'est la puissance de l'appareil, pas l'énergie consommée. Il manque la durée d'utilisation."]}
 ]},

 {titre:"Le circuit électrique : tension, intensité, résistance", blocs:[
  {t:"p", x:"Dans un circuit, trois grandeurs se répondent en permanence. La **tension** $U$, en volts, mesure la « poussée » entre deux points. L'**intensité** $I$, en ampères, mesure le débit de charges qui passe. La **résistance** $R$, en ohms, mesure la difficulté à laisser passer."},
  {t:"formule", titre:"Loi d'Ohm", x:"$U = R × I$", note:"$U$ en @u{V} · $R$ en @u{Ω} · $I$ en @u{A}. Elle ne vaut que pour un conducteur ohmique — une résistance, pas une pile ni une diode."},
  {t:"fig", titre:"Un circuit simple, en série",
   vue:[0,0,8,6], w:360, h:270, grille:false, axes:false,
   objets:[
    {t:"dip", type:"pile", de:[1,1], a:[1,5], nom:"G"},
    {t:"dip", type:"resistor", de:[1,5], a:[7,5], nom:"R"},
    {t:"dip", type:"lampe", de:[7,5], a:[7,1], nom:"L"},
    {t:"dip", type:"inter", de:[7,1], a:[1,1], nom:"K", ferme:true, cote:-1}
   ],
   note:"En série, la même intensité traverse tous les dipôles. Le générateur fournit, les autres consomment."},
  {t:"formule", titre:"Puissance reçue par un dipôle", x:"$P = U × I$", note:"$P$ en @u{W} · $U$ en @u{V} · $I$ en @u{A}. Cette formule vaut pour **tout** dipôle, ohmique ou non."}
  ,{t:"figi", nom:"ohm"}
  ,{t:"p", x:"Fais varier la tension : l'intensité suit, et la lampe s'éclaire. Augmente maintenant la résistance à tension constante : l'intensité chute, la lampe faiblit. C'est exactement ce que dit $U = R × I$ — et la puissance, elle, suit les deux à la fois."},
  {t:"exemple", titre:"Exemple guidé — lire une plaque signalétique", enonce:"Une bouilloire porte l'inscription « $230$ @u{V} — $2200$ @u{W} ». Quelle intensité la traverse ? Quelle énergie consomme-t-elle en $3$ minutes ?", etapes:[
   {q:"Trouver l'intensité", r:"$P = U × I$ donne $I = @f{P}{U} = @f{2200}{230} ≈ 9{,}6$ @u{A}."},
   {q:"Est-ce plausible ?", r:"Oui : les prises domestiques supportent jusqu'à $16$ @u{A}. Une bouilloire est parmi les appareils les plus gourmands de la maison."},
   {q:"Convertir la durée", r:"$3$ minutes $= 3 × 60 = 180$ @u{s}."},
   {q:"Calculer l'énergie", r:"$E = P × Δt = 2200 × 180 = 396 000$ @u{J}, soit environ $4{,}0 × 10^{5}$ @u{J}."},
   {q:"En kilowattheures", r:"$E = @f{396 000}{3{,}6 × 10^{6}} = 0{,}11$ @u{kWh}. À $0{,}20$ € le @u{kWh}, cela coûte environ deux centimes."}
  ]}
 ]},

 {titre:"L'effet Joule : quand l'électricité chauffe", blocs:[
  {t:"idee", x:"Tout conducteur parcouru par un courant **s'échauffe**. Ce phénomène s'appelle l'**effet Joule** : une partie de l'énergie électrique devient de l'énergie thermique, qu'on le veuille ou non."},
  {t:"formule", titre:"Puissance dissipée par effet Joule",
   x:"$P_{Joule} = R × I^2$",
   note:"Cette forme se déduit de $P = U I$ et $U = R I$. L'intensité est **au carré** : elle pèse beaucoup plus lourd que la résistance."},
  {t:"p", x:"Le carré change tout. Doubler l'intensité **quadruple** l'échauffement. C'est pour cette raison que les lignes à haute tension transportent l'électricité sous des centaines de milliers de volts : à puissance transportée égale, une tension élevée signifie une intensité faible, donc des pertes divisées par le carré du facteur gagné."},
  {t:"tbl", head:["Situation","L'effet Joule est…","Pourquoi"], rows:[
   ["Radiateur électrique","**voulu**","C'est exactement ce qu'on cherche : chauffer"],
   ["Grille-pain, bouilloire","**voulu**","Toute l'énergie sert à chauffer"],
   ["Câble d'alimentation","subi","L'énergie perdue ne sert à rien"],
   ["Moteur, téléphone","subi","Il échauffe l'appareil et réduit son rendement"]
  ]},
  {t:"astuce", titre:"Trois écritures d'une même puissance", x:"$P = U I$, $P = R I^2$ et $P = @f{U^2}{R}$ donnent le même résultat pour un conducteur ohmique. Choisis celle dont tu as **les deux données** : c'est ce qui évite un calcul intermédiaire inutile."}
  ,{t:"methode", titre:"Choisir la bonne formule électrique", etapes:[
   "**Souligner les données de l'énoncé** avec leur unité : des volts, des ampères, des ohms, des watts, des secondes ?",
   "**Écrire ce qui est cherché**, avec son unité. C'est elle qui désigne la formule : des watts → une puissance, des joules → une énergie.",
   "**Choisir la formule qui relie ce qu'on a à ce qu'on cherche** : $U = RI$ entre les trois grandeurs du circuit ; $P = UI$ ou $P = RI^2$ pour une puissance ; $E = P Δt$ pour une énergie.",
   "**Convertir avant de calculer** : les durées en secondes pour des joules, en heures pour des @u{kWh}.",
   "**Vérifier l'ordre de grandeur** : une ampoule fait quelques @u{W}, un radiateur quelques milliers."
  ], exemple:"« Une résistance de $20$ @u{Ω} parcourue par $1{,}5$ @u{A} : quelle puissance ? » On a $R$ et $I$, on cherche des watts → $P = R I^2 = 20 × 2{,}25 = 45$ @u{W}."}
 ]},

 {titre:"Bilan de puissance et rendement", blocs:[
  {t:"p", x:"Un appareil reçoit de l'énergie, en convertit une partie en ce qu'on lui demande, et perd le reste — presque toujours en chaleur. Le **bilan de puissance** décrit ce partage, et le **rendement** le résume en un nombre."},
  {t:"formule", titre:"Rendement d'un appareil",
   x:"$η = @f{P_{utile}}{P_{reçue}}$",
   note:"Sans unité, toujours compris entre 0 et 1. On l'exprime souvent en pourcentage."},
  {t:"fig", titre:"Le bilan de puissance d'un moteur",
   vue:[0,0,10,5], w:430, h:200, grille:false, axes:false,
   objets:[
    {t:"rect", x:3.4, y:1.6, w:3, h:1.9, couleur:"bleu", nom:"moteur"},
    {t:"vec", de:[0.4,2.5], a:[3.2,2.5], couleur:"ambre"},
    {t:"texte", x:1.8, y:3.1, txt:"reçue 1000 W", couleur:"ambre", taille:12},
    {t:"vec", de:[6.6,2.5], a:[9.4,2.5], couleur:"vert"},
    {t:"texte", x:8.1, y:3.1, txt:"utile 750 W", couleur:"vert", taille:12},
    {t:"vec", de:[4.9,1.4], a:[4.9,0.3], couleur:"rouge"},
    {t:"texte", x:6.9, y:0.6, txt:"perdue 250 W", couleur:"rouge", taille:12}
   ],
   note:"Tout ce qui entre ressort : ce qui n'est pas utile est perdu, presque toujours en chaleur."},
  {t:"formule", titre:"La conservation de l'énergie",
   x:"$P_{reçue} = P_{utile} + P_{perdue}$",
   note:"Rien ne se perd vraiment : l'énergie « perdue » est simplement partie sous une forme qui ne nous sert pas."},
  {t:"exemple", titre:"Exemple guidé — le rendement d'un moteur", enonce:"Un moteur reçoit $1000$ @u{W} et fournit $750$ @u{W} de puissance mécanique. Calculer son rendement et la puissance perdue.", etapes:[
   {q:"Le rendement", r:"$η = @f{P_{utile}}{P_{reçue}} = @f{750}{1000} = 0{,}75$, soit $75$ %."},
   {q:"La puissance perdue", r:"$P_{perdue} = P_{reçue} - P_{utile} = 1000 - 750 = 250$ @u{W}."},
   {q:"Sous quelle forme ?", r:"Essentiellement en chaleur, par effet Joule dans les bobinages, et un peu en frottements. C'est pour cela qu'un moteur chauffe."},
   {q:"Le contrôle", r:"Un rendement supérieur à 1 serait impossible : cela signifierait qu'un appareil fournit plus qu'il ne reçoit. Si tu en trouves un, reprends le calcul."}
  ]},
  {t:"piege", titre:"Utile sur reçue, et pas l'inverse", x:"Le rendement met **l'utile au numérateur**. Inverser la fraction donne un nombre supérieur à 1, ce qui n'a aucun sens physique. Ce contrôle repère l'erreur immédiatement."}
  ,{t:"methode", titre:"Calculer le coût d'une consommation", etapes:[
   "**Convertir la puissance en kilowatts** : diviser les watts par 1000.",
   "**Convertir la durée en heures** : $30$ minutes valent $0{,}5$ @u{h}.",
   "**Multiplier les deux** : on obtient directement des kilowattheures.",
   "**Multiplier par le prix du @u{kWh}** pour obtenir des euros."
  ], exemple:"Une plaque de $2000$ @u{W} pendant $45$ minutes : $2{,}0$ @u{kW} $× 0{,}75$ @u{h} $= 1{,}5$ @u{kWh}, soit $1{,}5 × 0{,}20 = 0{,}30$ € à $0{,}20$ € le @u{kWh}."}

  ,{t:"check", q:"Deux appareils consomment la même énergie. Le premier fait $2000$ @u{W} pendant $30$ minutes. Combien de temps fonctionne le second, qui fait $500$ @u{W} ?",
   choix:["2 heures","30 minutes","7 minutes 30","4 heures"], bonne:0,
   expl:["Exact : quatre fois moins puissant, donc quatre fois plus longtemps. $30$ minutes $× 4 = 2$ heures.",
         "Ce serait le cas si les deux avaient la même puissance. Or le second est quatre fois plus faible.",
         "Tu as divisé par 4 au lieu de multiplier. Un appareil moins puissant met **plus** de temps à consommer la même énergie.",
         "Le rapport des puissances est $@f{2000}{500} = 4$, pas 8. La durée est donc multipliée par 4."]}
 ]},

{titre:"Ce qu'une batterie a dans le ventre", blocs:[
  {t:"idee", x:"Une batterie ne contient pas du courant : elle contient de l'**énergie**, en réserve. Ce qu'on lit sur son étiquette — des ampères-heures — n'est pas cette énergie, mais une **charge**. Pour passer de l'une à l'autre, il faut la tension."},
  {t:"p", x:"Regarde une batterie de téléphone : « 4000 mAh, 3,85 V ». Le premier nombre dit combien de charges elle peut débiter ; le second, avec quelle poussée. C'est le produit des deux qui donne l'énergie disponible — de la même façon qu'un réservoir se juge à son volume **et** à ce qu'on y met."},
  {t:"formule", titre:"De la capacité à l'énergie",
   x:"$E = Q × U$",
   note:"$Q$ en @u{A·h} · $U$ en @u{V} · $E$ en @u{W·h}. Et $1$ @u{W·h} $= 3600$ @u{J}, puisqu'un watt pendant une heure fait $3600$ joules."},
  {t:"tbl", head:["Source","Capacité","Tension","Énergie"], rows:[
   ["Pile AA","$2{,}5$ @u{A·h}","$1{,}5$ @u{V}","$3{,}8$ @u{W·h}"],
   ["Batterie de téléphone","$4{,}0$ @u{A·h}","$3{,}85$ @u{V}","$15$ @u{W·h}"],
   ["Batterie de vélo électrique","$14$ @u{A·h}","$36$ @u{V}","$500$ @u{W·h}"],
   ["Batterie de voiture électrique","$120$ @u{A·h}","$400$ @u{V}","$48$ @u{kW·h}"]
  ]},
  {t:"p", x:"Ce tableau montre pourquoi la capacité seule ne veut rien dire. La batterie de vélo n'affiche que trois fois et demie plus d'ampères-heures que celle du téléphone — et pourtant elle contient **trente fois** plus d'énergie. L'écart ne vient pas de la capacité : il vient de la tension, $36$ @u{V} au lieu de $3{,}85$."},
  {t:"methode", titre:"Calculer une autonomie", etapes:[
   "**Calculer l'énergie stockée** : $E = Q × U$, avec la capacité en @u{A·h} et la tension en volts. Le résultat est en wattheures.",
   "**Relever la puissance consommée** par l'appareil, en watts.",
   "**Diviser l'énergie par la puissance** : l'autonomie sort directement en heures.",
   "**Convertir en minutes si besoin**, et retrancher une marge : une batterie ne se vide jamais complètement, et son rendement n'est pas de 100 %.",
   "**Vérifier l'ordre de grandeur** : quelques heures pour un téléphone, quelques dizaines d'heures pour une lampe, quelques centaines de kilomètres pour une voiture."
  ], exemple:"Batterie de $4{,}0$ @u{A·h} sous $3{,}85$ @u{V} : $E = 15{,}4$ @u{W·h}. Un téléphone qui consomme $1{,}5$ @u{W} en usage tient donc $@f{15{,}4}{1{,}5} ≈ 10$ heures."},
  {t:"piege", titre:"Un ampère-heure n'est pas une énergie", x:"Comparer deux batteries par leurs seuls @u{A·h} n'a aucun sens si leurs tensions diffèrent. C'est comme comparer deux réservoirs par leur diamètre en ignorant leur hauteur. La seule grandeur comparable est le **wattheure**."},
  {t:"exemple", titre:"Exemple guidé — l'autonomie d'un vélo électrique", enonce:"Une batterie de $14$ @u{A·h} sous $36$ @u{V} alimente un moteur qui consomme en moyenne $250$ @u{W}. Quelle autonomie, en heures ? Et sur combien de kilomètres, à $20$ @u{km/h} ?", etapes:[
   {q:"L'énergie stockée", r:"$E = Q × U = 14 × 36 = 504$ @u{W·h}, soit environ un demi-kilowattheure."},
   {q:"L'autonomie en temps", r:"$@f{E}{P} = @f{504}{250} ≈ 2{,}0$ heures de roulage à pleine assistance."},
   {q:"La distance", r:"À $20$ @u{km/h} pendant $2{,}0$ heures : $20 × 2{,}0 = 40$ @u{km}."},
   {q:"Pourquoi les constructeurs annoncent plus", r:"Parce qu'en usage réel, l'assistance ne fonctionne pas en permanence : sur le plat et en descente, le moteur consomme bien moins que $250$ @u{W}. L'autonomie annoncée suppose un usage moyen, pas un usage à pleine puissance."},
   {q:"Le contrôle", r:"$500$ @u{W·h} pour $40$ @u{km}, cela fait $12{,}5$ @u{W·h} par kilomètre. Une voiture électrique en consomme environ $150$ : douze fois plus, pour transporter une tonne au lieu de vingt kilos de vélo. Cohérent."}
  ]},
  {t:"check", q:"Deux batteries : l'une de $10$ @u{A·h} sous $12$ @u{V}, l'autre de $5$ @u{A·h} sous $36$ @u{V}. Laquelle contient le plus d'énergie ?",
   choix:["La seconde : $180$ @u{W·h} contre $120$","La première, elle a plus d'ampères-heures",
          "Les deux contiennent la même énergie","On ne peut pas comparer sans connaître la marque"], bonne:0,
   expl:["Exact : $5 × 36 = 180$ @u{W·h} contre $10 × 12 = 120$ @u{W·h}. La tension trois fois plus élevée l'emporte largement sur la capacité deux fois plus faible.",
         "C'est justement le piège. Les ampères-heures ne mesurent qu'une charge : sans la tension, ils ne disent rien de l'énergie.",
         "$120$ et $180$ @u{W·h} : l'écart est de moitié. Il suffit de faire les deux produits pour trancher.",
         "La marque n'entre pas dans le calcul : capacité multipliée par tension, et la comparaison est faite."]}
 ]},
 {titre:"Atelier — ce que coûte vraiment un chauffe-eau", blocs:[
  {t:"p", x:"Toutes les notions du chapitre servent dans cet atelier, et dans l'ordre où elles servent en vrai : la puissance, la durée, le kilowattheure, le prix, puis le rendement. C'est toi qui calcules chaque valeur."},
  {t:"atelier", titre:"La facture annuelle d'un chauffe-eau",
   enonce:"Un chauffe-eau porte l'inscription « $2000$ @u{W} ». Il fonctionne en moyenne $2$ heures par jour. Le kilowattheure est facturé $0{,}20$ €. Son rendement est de $90$ %.",
   etapes:[
    {q:"Quelle énergie consomme-t-il en une journée, en @u{kWh} ?",
     rep:4, tol:0.05, unite:"kWh",
     aide:"Un kilowattheure, c'est un kilowatt pendant une heure. Convertis d'abord la puissance en kilowatts.",
     diag:[{v:4000, m:"$4000$ serait le résultat en wattheures. La question demande des **kilo**wattheures : divise par mille."},
           {v:1000, m:"Tu as divisé la puissance par la durée. L'énergie est le **produit** de la puissance par le temps."},
           {v:2, m:"$2$ @u{kW} est la puissance, ou $2$ @u{h} la durée. L'énergie est leur produit."},
           {v:7200000, m:"$7{,}2 × 10^6$ @u{J} est bien l'énergie, mais en joules. Le @u{kWh} est une autre unité, faite pour éviter ces grands nombres."}],
     expl:"$2000$ @u{W} $= 2{,}0$ @u{kW}, et $2{,}0 × 2 = 4{,}0$ @u{kWh}. **Pourquoi cette unité existe.** En joules, la même énergie s'écrit $7{,}2$ millions. Le kilowattheure a été inventé pour que les factures restent lisibles : il suffit de multiplier des kilowatts par des heures, sans convertir quoi que ce soit. C'est la seule formule de physique qu'on lit tous les mois sans le savoir."},

    {q:"Combien cela coûte-t-il par jour, en euros ?",
     rep:0.80, tol:0.005, unite:"€",
     aide:"Le prix du kilowattheure multiplie le nombre de kilowattheures consommés.",
     diag:[{v:20, m:"Tu as multiplié par $20$ au lieu de $0{,}20$. Le prix est de vingt **centimes**, pas vingt euros."},
           {v:0.05, m:"La division est inversée : c'est l'énergie qu'on multiplie par le prix unitaire, pas l'inverse."},
           {v:4.2, m:"Tu as additionné le prix à l'énergie. Ce sont deux grandeurs différentes : il faut les multiplier."}],
     expl:"$4{,}0 × 0{,}20 = 0{,}80$ € par jour. **Le contrôle qui rassure.** Quatre kilowattheures à vingt centimes, c'est un peu moins d'un euro : l'ordre de grandeur est plausible pour deux heures de chauffe. Un résultat de $20$ € aurait dû alerter immédiatement — personne ne paie vingt euros de chauffe-eau par jour."},

    {q:"Et sur une année entière de $365$ jours, en euros ?",
     rep:292, tol:1, unite:"€",
     aide:"Le coût d'un jour, répété trois cent soixante-cinq fois.",
     diag:[{v:1460, m:"Tu as multiplié les $4{,}0$ @u{kWh} par $365$ : c'est l'énergie annuelle, en @u{kWh}. Il reste à la multiplier par le prix."},
           {v:73, m:"Tu as multiplié $0{,}20$ par $365$. Il faut partir du coût **journalier**, qui est de $0{,}80$ €."}],
     expl:"$0{,}80 × 365 = 292$ € par an. **Ce que ce nombre change.** Quatre-vingts centimes par jour ne font peur à personne ; près de trois cents euros par an, si. C'est tout l'intérêt de ramener une consommation à l'année : c'est la seule échelle à laquelle une petite dépense quotidienne devient une décision. On peut faire le même calcul pour une box internet ou un vieux congélateur."},

    {q:"Passons au rendement. Quelle puissance sert réellement à chauffer l'eau, en @u{W} ?",
     rep:1800, tol:5, unite:"W",
     aide:"Le rendement est la part de la puissance reçue qui devient utile. Quatre-vingt-dix pour cent de deux mille watts.",
     diag:[{v:200, m:"$200$ @u{W} est la puissance **perdue**, les $10$ % restants. La question porte sur la partie utile."},
           {v:2222, m:"Tu as divisé par $0{,}90$ au lieu de multiplier. Diviser donnerait la puissance à fournir pour obtenir $2000$ @u{W} utiles — ce n'est pas la question."},
           {v:90, m:"$90$ est le rendement en pourcentage, pas une puissance."}],
     expl:"$2000 × 0{,}90 = 1800$ @u{W}. **Ce que devient le reste.** Les $200$ @u{W} manquants ne disparaissent pas : ils chauffent la cuve, les tuyaux, l'air autour. Un rendement de $90$ % est excellent — un moteur thermique de voiture plafonne vers $35$ %, une vieille ampoule à filament ne dépassait pas $5$ %. Le rendement ne se calcule jamais sur la facture : la facture, elle, compte les $2000$ @u{W} entiers."},

    {q:"Dernière question : quelle énergie est perdue chaque jour, en @u{kWh} ?",
     rep:0.40, tol:0.005, unite:"kWh",
     aide:"Il manque dix pour cent de l'énergie consommée dans la journée.",
     diag:[{v:3.6, m:"$3{,}6$ @u{kWh} est l'énergie **utile**, les $90$ %. On demande ce qui est perdu."},
           {v:0.2, m:"$0{,}20$ est le prix du kilowattheure, ou la puissance perdue en kilowatts. L'énergie perdue se compte sur les deux heures de fonctionnement."},
           {v:200, m:"$200$ @u{W} est la **puissance** perdue. Multipliée par les $2$ heures, elle donne $400$ @u{Wh}, soit $0{,}40$ @u{kWh}."}],
     expl:"$4{,}0 × 0{,}10 = 0{,}40$ @u{kWh}, soit $0{,}08$ € par jour et environ $29$ € par an. **Deux chemins, un seul résultat.** On peut aussi passer par la puissance : $200$ @u{W} perdus pendant $2$ heures font $400$ @u{Wh}, c'est-à-dire $0{,}40$ @u{kWh}. Quand deux raisonnements différents tombent sur le même nombre, c'est le meilleur contrôle qui existe — bien plus fiable que de refaire deux fois le même calcul."}
   ],
   bilan:"Une consommation se lit toujours en trois temps : **la puissance** (ce que l'appareil tire à chaque instant), **la durée** (combien de temps il la tire), **le prix** (ce que coûte le produit des deux). Le rendement, lui, ne change rien à la facture : il dit seulement quelle part de ce qu'on paie fait le travail attendu."}
 ]},

 {titre:"Récapitulatif", blocs:[
  {t:"tbl", head:["La question ressemble à…","La formule à utiliser"], rows:[
   ["« Quelle énergie consommée ? »","$E = P × Δt$, avec $Δt$ en secondes"],
   ["« Quelle intensité traverse l'appareil ? »","$I = @f{P}{U}$"],
   ["« Quelle tension aux bornes de la résistance ? »","$U = R × I$"],
   ["« Quelle puissance dissipée par effet Joule ? »","$P = R × I^2$"],
   ["« Quel rendement ? »","$η = @f{P_{utile}}{P_{reçue}}$"],
   ["« Combien coûte cette consommation ? »","Passer en @u{kWh}, puis multiplier par le prix"]
  ]},
  {t:"idee", x:"Toute l'énergie reçue se retrouve quelque part : une partie fait ce qu'on demande, le reste chauffe l'air. C'est le seul principe de ce chapitre — tout le reste n'en est que la mise en équations."}
 ]}
],
exos:[
 {id:"el1", niveau:1, type:"num", enonce:"Un appareil branché sous $230$ @u{V} est traversé par une intensité de $2{,}0$ @u{A}. Quelle est sa puissance, en @u{W} ?",
  rep:460, tol:1, unite:"W",
  diag:[{v:115, m:"Tu as divisé la tension par l'intensité : cela donne une résistance en ohms, pas une puissance. La puissance est un **produit** : $P = U × I$."},
        {v:232, m:"Tu as additionné les deux valeurs. Une tension et une intensité ne s'additionnent pas — elles se multiplient pour donner une puissance."},
        {v:0.0087, m:"Tu as divisé l'intensité par la tension. La formule est $P = U × I$."}],
  corr:["**Ce que dit l'énoncé.** Une tension $U = 230$ @u{V} et une intensité $I = 2{,}0$ @u{A}. On cherche la puissance.",
        "**Ce que représente chaque grandeur.** La tension est la « poussée » électrique, l'intensité le débit de charges. La puissance mesure l'énergie transférée par seconde.",
        "**La formule.** $P = U × I$. Elle vaut pour **tout** dipôle, qu'il soit ohmique ou non.",
        "**Je remplace.** $P = 230 × 2{,}0$.",
        "**Je calcule.** $P = 460$ @u{W}.",
        "**Je vérifie l'ordre de grandeur.** $460$ @u{W} : c'est la puissance d'un petit radiateur ou d'un sèche-cheveux. Plausible pour un appareil sur une prise domestique."],
  indice:"$P = U × I$ : une multiplication."},

 {id:"el2", niveau:1, type:"num", enonce:"Une lampe de $60$ @u{W} reste allumée pendant $5$ minutes. Quelle énergie a-t-elle consommée, en @u{J} ?",
  rep:18000, tol:10, unite:"J",
  diag:[{v:300, m:"Tu as laissé la durée en minutes. Dans $E = P × Δt$, la durée doit être en **secondes** : $5$ min $= 300$ @u{s}. Ton résultat est 60 fois trop petit."},
        {v:12, m:"Tu as divisé la puissance par la durée. L'énergie est le produit des deux : plus l'appareil reste allumé, plus il consomme."},
        {v:0.005, m:"Tu as inversé la fraction. $E = P × Δt$ est une multiplication."}],
  corr:["**Ce que dit l'énoncé.** Une lampe de $60$ @u{W} allumée $5$ minutes. On cherche l'énergie consommée, en joules.",
        "**La différence entre puissance et énergie.** La puissance est le débit ; l'énergie est le total accumulé. Pour passer de l'une à l'autre, on multiplie par la durée : $E = P × Δt$.",
        "**Le piège des unités.** Un watt vaut un joule **par seconde**. Pour obtenir des joules, la durée doit donc être en **secondes**.",
        "**Je convertis.** $5$ minutes $= 5 × 60 = 300$ @u{s}.",
        "**Je remplace et je calcule.** $E = 60 × 300 = 18 000$ @u{J}, soit $1{,}8 × 10^{4}$ @u{J}.",
        "**Je vérifie.** En gardant les minutes, j'aurais trouvé $300$ @u{J} : soixante fois trop peu. Le contrôle est simple — une lampe consomme des milliers de joules en quelques minutes, pas quelques centaines."],
  indice:"Convertis la durée en secondes avant de multiplier."},

 {id:"el3", niveau:2, type:"num", enonce:"Une résistance de $20$ @u{Ω} est traversée par une intensité de $1{,}5$ @u{A}. Quelle puissance dissipe-t-elle par effet Joule, en @u{W} ?",
  rep:45, tol:0.5, unite:"W",
  diag:[{v:30, m:"Tu as calculé $R × I$ sans élever l'intensité au carré. La formule est $P = R × I^2$, et $1{,}5^2 = 2{,}25$."},
        {v:13.3, m:"Tu as divisé la résistance par l'intensité. La puissance dissipée est un produit."},
        {v:900, m:"Tu as élevé au carré le produit entier : $(20 × 1{,}5)^2$. Le carré ne porte que sur l'intensité."}],
  corr:["**Ce que dit l'énoncé.** Une résistance $R = 20$ @u{Ω} traversée par $I = 1{,}5$ @u{A}. On cherche la puissance dissipée par effet Joule.",
        "**Ce qu'est l'effet Joule.** Tout conducteur parcouru par un courant s'échauffe : une partie de l'énergie électrique devient de la chaleur.",
        "**La formule et sa particularité.** $P = R × I^2$. L'intensité est **au carré** : c'est elle qui pèse le plus lourd, bien plus que la résistance.",
        "**Étape 1 — je calcule le carré en premier.** $1{,}5^2 = 1{,}5 × 1{,}5 = 2{,}25$. Le carré ne porte que sur l'intensité, pas sur le produit entier.",
        "**Étape 2 — je multiplie par la résistance.** $P = 20 × 2{,}25 = 45$ @u{W}.",
        "**Je mesure la portée du carré.** Avec une intensité doublée, $3{,}0$ @u{A}, on aurait $20 × 9 = 180$ @u{W} : quatre fois plus. C'est pourquoi on transporte l'électricité à haute tension, donc à faible intensité."],
  indice:"Le carré porte uniquement sur l'intensité : calcule-le d'abord."},

 {id:"el4", niveau:2, type:"num", enonce:"Un moteur reçoit une puissance électrique de $800$ @u{W} et fournit $600$ @u{W} de puissance mécanique. Quel est son rendement, en pourcentage ?",
  rep:75, tol:0.5, unite:"%",
  diag:[{v:133, m:"Tu as inversé la fraction. Le rendement met la puissance **utile** au numérateur, et ne dépasse jamais $100$ %."},
        {v:0.75, m:"Le calcul est juste, mais la réponse est demandée en pourcentage : $0{,}75$ correspond à $75$ %."},
        {v:200, m:"$200$ @u{W} est la puissance **perdue** ($800 - 600$), pas le rendement. Le rendement est un rapport, sans unité."}],
  corr:["**Ce que dit l'énoncé.** Le moteur reçoit $800$ @u{W} et en fournit $600$ @u{W} d'utile. On cherche son rendement en pourcentage.",
        "**Ce qu'est un rendement.** La part de ce qui entre qui sert vraiment à ce qu'on demande. Le reste s'échappe, presque toujours en chaleur.",
        "**La formule.** $η = @f{P_{utile}}{P_{reçue}}$ : l'utile au **numérateur**. Dans l'autre sens, on obtiendrait un nombre supérieur à 1, ce qui n'a aucun sens.",
        "**Je remplace.** $η = @f{600}{800}$.",
        "**Je calcule.** $η = 0{,}75$, soit $75$ % en multipliant par $100$.",
        "**Je vérifie et j'interprète.** Le résultat est bien compris entre $0$ et $1$. Les $25$ % restants, soit $800 - 600 = 200$ @u{W}, chauffent les bobinages : c'est pour cela qu'un moteur devient tiède."],
  indice:"Puissance utile divisée par puissance reçue, puis multiplié par 100."},

 {id:"el5", niveau:2, type:"num", enonce:"Une plaque de cuisson de $2000$ @u{W} fonctionne $45$ minutes. Le @u{kWh} coûte $0{,}20$ €. Combien cela coûte-t-il, en euros ?",
  rep:0.3, tol:0.005, unite:"€",
  diag:[{v:0.4, m:"Tu as compté une heure complète. La plaque fonctionne $45$ minutes, soit $0{,}75$ heure."},
        {v:300, m:"Tu as gardé les watts au lieu de convertir en kilowatts. $2000$ @u{W} $= 2$ @u{kW}."},
        {v:1.5, m:"Tu as calculé l'énergie en @u{kWh} ($1{,}5$) mais oublié de la multiplier par le prix du @u{kWh}."}],
  corr:["**Ce que dit l'énoncé.** Une plaque de $2000$ @u{W} pendant $45$ minutes, à $0{,}20$ € le @u{kWh}.",
        "**Pourquoi ne pas travailler en joules.** Les factures d'électricité comptent en kilowattheures. Or $1$ @u{kWh} $=$ $1$ @u{kW} pendant $1$ @u{h} : il suffit d'avoir des kilowatts et des heures.",
        "**Étape 1 — la puissance en kilowatts.** $2000$ @u{W} $= @f{2000}{1000} = 2{,}0$ @u{kW}.",
        "**Étape 2 — la durée en heures.** $45$ minutes $= @f{45}{60} = 0{,}75$ @u{h}.",
        "**Étape 3 — l'énergie.** $E = 2{,}0 × 0{,}75 = 1{,}5$ @u{kWh}.",
        "**Étape 4 — le coût.** $1{,}5 × 0{,}20 = 0{,}30$ €. Trente centimes pour trois quarts d'heure de plaque : un ordre de grandeur qu'on peut vérifier sur une vraie facture."],
  indice:"Le kilowattheure se calcule avec des kilowatts et des heures — pas des watts ni des minutes."},

 {id:"el6", niveau:3, type:"num", enonce:"Une résistance de $50$ @u{Ω} est soumise à une tension de $12$ @u{V}. Quelle intensité la traverse, en @u{A} ?",
  rep:0.24, tol:0.005, unite:"A",
  diag:[{v:600, m:"Tu as multiplié la tension par la résistance. La loi d'Ohm s'écrit $U = R × I$ : pour trouver $I$, il faut **diviser** $U$ par $R$."},
        {v:4.17, m:"Tu as divisé la résistance par la tension. C'est l'inverse : $I = @f{U}{R}$."},
        {v:2.4, m:"Erreur d'un facteur 10 : $@f{12}{50} = 0{,}24$, et non $2{,}4$."}],
  corr:["**Ce que dit l'énoncé.** Une résistance $R = 50$ @u{Ω} sous une tension $U = 12$ @u{V}. On cherche l'intensité.",
        "**La loi à utiliser.** La loi d'Ohm, $U = R × I$, qui relie les trois grandeurs d'un conducteur ohmique.",
        "**J'isole l'inconnue avant de remplacer.** Dans $U = R × I$, je divise les deux membres par $R$ : $I = @f{U}{R}$.",
        "**Je remplace.** $I = @f{12}{50}$.",
        "**Je calcule.** $I = 0{,}24$ @u{A}, soit $240$ @u{mA}.",
        "**Je vérifie le sens.** Plus la résistance est grande, plus l'intensité est faible : c'est logique, une résistance **freine** le courant. Avec $50$ @u{Ω}, une intensité inférieure à l'ampère est attendue."],
  indice:"Isole $I$ dans $U = R × I$ avant de remplacer."},

 {id:"el7", niveau:3, type:"qcm", enonce:"Pourquoi transporte-t-on l'électricité sous très haute tension sur les lignes ?",
  choix:["Parce qu'à puissance égale, une tension élevée donne une intensité faible, donc moins de pertes par effet Joule",
         "Parce que la haute tension va plus vite",
         "Parce que les pertes augmentent avec la tension","Parce que cela permet d'augmenter la résistance des câbles"], bonne:0,
  diag:["",
        "L'électricité se propage à la même vitesse quelle que soit la tension. Ce n'est pas une question de rapidité.",
        "C'est l'inverse : à puissance transportée constante, augmenter la tension **réduit** l'intensité, et donc les pertes.",
        "Augmenter la résistance des câbles augmenterait les pertes. On cherche au contraire à les minimiser."],
  corr:["**Ce que demande la question.** Pourquoi les lignes électriques fonctionnent sous très haute tension.",
        "**Étape 1 — où sont les pertes ?** Dans les câbles, qui ont une résistance $R$. La puissance perdue vaut $P_{Joule} = R × I^2$ : elle dépend de l'**intensité**, au carré.",
        "**Étape 2 — ce qu'on doit transporter.** Une puissance donnée, fixée par la consommation : $P = U × I$. C'est cette puissance-là qu'on ne peut pas changer.",
        "**Étape 3 — la marge de manœuvre.** À puissance fixée, $U$ et $I$ sont liés : si on multiplie la tension par $100$, l'intensité est divisée par $100$.",
        "**Étape 4 — l'effet sur les pertes.** Comme les pertes dépendent du **carré** de l'intensité, les diviser par $100$ divise les pertes par $100^2 = 10 000$.",
        "**Je conclus.** C'est pourquoi les lignes fonctionnent sous $400 000$ @u{V} plutôt que sous $230$ @u{V} : la tension est élevée précisément pour rendre l'intensité, et donc les pertes, minuscules."],
  indice:"Regarde de quelle grandeur dépendent les pertes, et à quelle puissance."},

 {id:"el8", niveau:3, type:"num", enonce:"Un chauffe-eau de $2400$ @u{W} a un rendement de $90$ %. Quelle puissance sert réellement à chauffer l'eau, en @u{W} ?",
  rep:2160, tol:5, unite:"W",
  diag:[{v:2667, m:"Tu as divisé par le rendement au lieu de multiplier. La puissance utile est forcément **inférieure** à la puissance reçue."},
        {v:240, m:"$240$ @u{W} est la puissance **perdue** ($10$ % de $2400$). La question porte sur la puissance utile, soit les $90$ % restants."},
        {v:216, m:"Erreur d'un facteur 10 : $2400 × 0{,}90 = 2160$, pas $216$."}],
  corr:["**Ce que dit l'énoncé.** Un chauffe-eau reçoit $2400$ @u{W} avec un rendement de $90$ %. On cherche la puissance réellement utile.",
        "**Ce que dit le rendement.** $90$ % signifie que $90$ parts sur $100$ de ce qui entre servent vraiment à chauffer l'eau. Le reste s'échappe par les parois.",
        "**Je pars de la formule.** $η = @f{P_{utile}}{P_{reçue}}$.",
        "**J'isole l'utile.** En multipliant les deux membres par $P_{reçue}$ : $P_{utile} = η × P_{reçue}$.",
        "**Je convertis le pourcentage et je calcule.** $90$ % $= 0{,}90$, donc $P_{utile} = 0{,}90 × 2400 = 2160$ @u{W}.",
        "**Je vérifie.** L'utile doit être **inférieur** au reçu : $2160 < 2400$. Cohérent. La différence, $240$ @u{W}, est exactement les $10$ % perdus."],
  indice:"La puissance utile est une fraction de la puissance reçue : multiplie par le rendement."},

{id:"el9", niveau:1, type:"num", enonce:"Un radiateur de $1500$ @u{W} fonctionne $4$ heures. Quelle énergie a-t-il consommée, en @u{kWh} ?",
  rep:6, tol:0.05, unite:"kWh",
  diag:[{v:6000, m:"Tu as multiplié en watts : $1500 × 4 = 6000$ @u{Wh}. La question demande des **kilo**wattheures : il faut diviser par $1000$."},
        {v:375, m:"Tu as divisé la puissance par la durée. L'énergie est un produit : plus l'appareil fonctionne longtemps, plus il consomme."},
        {v:1.5, m:"$1{,}5$ @u{kW} est la puissance convertie. Il reste à la multiplier par la durée."}],
  corr:["**Pourquoi les @u{kWh} sont commodes.** Un kilowattheure, c'est un kilowatt pendant une heure. Il suffit donc d'avoir des kilowatts et des heures — aucune conversion en secondes.",
        "**Étape 1 — la puissance en kilowatts.** $1500$ @u{W} $= @f{1500}{1000} = 1{,}5$ @u{kW}.",
        "**Étape 2 — la durée est déjà en heures.** $4$ @u{h}, rien à convertir.",
        "**Étape 3 — je multiplie.** $E = 1{,}5 × 4$.",
        "**Je calcule.** $E = 6$ @u{kWh}.",
        "**Je vérifie sur le réel.** À environ $0{,}20$ € le @u{kWh}, ces quatre heures de chauffage coûtent $1{,}20$ €. Un ordre de grandeur qu'on peut confronter à une vraie facture."],
  indice:"Des kilowatts multipliés par des heures donnent directement des kilowattheures."},

 {id:"el10", niveau:2, type:"num", enonce:"Une résistance $R = 6{,}0$ @u{Ω} est soumise à une tension $U = 12$ @u{V}. Quelle puissance dissipe-t-elle, en @u{W} ?",
  rep:24, tol:0.5, unite:"W",
  diag:[{v:72, m:"Tu as calculé $U × R$. Ce produit n'a pas de sens physique : la puissance vaut $U × I$, et il faut d'abord trouver $I$."},
        {v:2, m:"$2{,}0$ @u{A} est l'**intensité**, pas la puissance. Il reste à la multiplier par la tension."},
        {v:12, m:"Tu as recopié la tension. Une tension est en volts, une puissance en watts."}],
  corr:["**Ce que donne l'énoncé.** Une résistance et une tension. Ce qu'on cherche : une puissance.",
        "**Le chemin le plus court.** Trois écritures donnent la puissance : $P = UI$, $P = RI^2$ et $P = @f{U^2}{R}$. La dernière utilise exactement les deux données dont je dispose.",
        "**Je remplace.** $P = @f{12^2}{6{,}0} = @f{144}{6{,}0}$.",
        "**Je calcule.** $P = 24$ @u{W}.",
        "**Je vérifie par l'autre chemin.** Loi d'Ohm : $I = @f{U}{R} = @f{12}{6{,}0} = 2{,}0$ @u{A}, puis $P = U × I = 12 × 2{,}0 = 24$ @u{W}. Même résultat.",
        "**Ce qu'il faut retenir.** Choisir la formule qui contient déjà les deux données évite un calcul intermédiaire — et donc une occasion de se tromper."],
  indice:"Trois écritures de la puissance existent : prends celle dont tu as déjà les deux grandeurs."},

 {id:"el11", niveau:2, type:"num", enonce:"On remplace une ampoule de $60$ @u{W} par une LED de $9$ @u{W}. Elles éclairent $5$ heures par jour. Quelle énergie économise-t-on chaque jour, en @u{Wh} ?",
  rep:255, tol:1, unite:"Wh",
  diag:[{v:300, m:"Tu as compté la consommation de l'ancienne ampoule seule ($60 × 5$). L'économie est la **différence** entre les deux consommations."},
        {v:45, m:"Tu as compté la consommation de la LED ($9 × 5$). C'est ce qu'on consomme encore, pas ce qu'on économise."},
        {v:51, m:"$51$ @u{W} est l'écart de **puissance**. Il reste à le multiplier par la durée pour obtenir une énergie."},
        {v:345, m:"Tu as additionné les deux consommations au lieu de les soustraire."}],
  corr:["**Ce que demande la question.** Non pas une consommation, mais une **économie** : la différence entre deux consommations.",
        "**Étape 1 — l'ancienne ampoule.** $E_1 = 60 × 5 = 300$ @u{Wh} par jour.",
        "**Étape 2 — la LED.** $E_2 = 9 × 5 = 45$ @u{Wh} par jour.",
        "**Étape 3 — la différence.** $300 - 45 = 255$ @u{Wh} économisés chaque jour.",
        "**Le raccourci équivalent.** On pouvait aussi faire l'écart de puissance d'abord : $(60 - 9) × 5 = 51 × 5 = 255$ @u{Wh}. Même résultat, une étape de moins.",
        "**J'interprète.** Sur une année, cela fait environ $93$ @u{kWh} pour une seule ampoule — et la LED éclaire autant. C'est tout l'intérêt du rendement."],
  indice:"Une économie est une différence : calcule les deux consommations, puis soustrais."},

 {id:"el12", niveau:3, type:"num", enonce:"Un chauffe-eau de $2000$ @u{W} a un rendement de $85$ %. Il fonctionne pendant $30$ minutes. Quelle énergie a réellement servi à chauffer l'eau, en @u{kJ} ?",
  rep:3060, tol:20, unite:"kJ",
  diag:[{v:3600, m:"$3600$ @u{kJ} est l'énergie **reçue** ($2000 × 1800$). Il reste à en prendre les $85$ % qui servent vraiment."},
        {v:1700, m:"Tu as gardé la durée en minutes quelque part, ou divisé par le rendement. Reprends : $2000 × 1800 × 0{,}85$."},
        {v:51, m:"Tu as gardé la durée en minutes : $2000 × 30 × 0{,}85 = 51 000$ @u{J}. Pour obtenir des joules, la durée doit être en **secondes**."},
        {v:3060000, m:"C'est le bon résultat, mais en joules. La question demande des kilojoules : $3 060 000$ @u{J} $= 3060$ @u{kJ}."}],
  corr:["**Ce que dit l'énoncé.** Une puissance reçue, un rendement, une durée. Ce qu'on cherche : l'énergie **utile**, celle qui chauffe vraiment l'eau.",
        "**Étape 1 — la durée en secondes.** $30$ minutes $= 30 × 60 = 1800$ @u{s}. Sans cette conversion, pas de joules.",
        "**Étape 2 — l'énergie reçue.** $E_{reçue} = P × Δt = 2000 × 1800 = 3 600 000$ @u{J}.",
        "**Étape 3 — la part utile.** Le rendement vaut $85$ % $= 0{,}85$ : $E_{utile} = 0{,}85 × 3 600 000$.",
        "**Je calcule.** $E_{utile} = 3 060 000$ @u{J}.",
        "**Étape 4 — je convertis et je vérifie.** $3 060 000$ @u{J} $= 3060$ @u{kJ}. Le résultat est bien **inférieur** à l'énergie reçue ($3600$ @u{kJ}) : les $540$ @u{kJ} manquants se sont échappés par les parois."],
  indice:"Trois temps : la durée en secondes, l'énergie reçue, puis la part utile."},

{id:"el13", niveau:2, type:"num", enonce:"Une batterie de téléphone porte l'inscription « $4{,}0$ @u{A·h} — $3{,}85$ @u{V} ». Quelle énergie stocke-t-elle, en @u{W·h} ?",
  rep:15.4, tol:0.1, unite:"W·h",
  diag:[{v:4, m:"Tu as recopié la capacité. Les ampères-heures mesurent une **charge**, pas une énergie : il faut encore multiplier par la tension."},
        {v:1.04, m:"Tu as divisé la capacité par la tension. L'énergie est le **produit** des deux."},
        {v:55440, m:"Tu as converti en joules ($15{,}4 × 3600$). La question demande des wattheures."}],
  corr:["**Ce que dit l'énoncé.** Une capacité en ampères-heures et une tension en volts. Ce qu'on cherche : une énergie.",
        "**Pourquoi la capacité ne suffit pas.** Les @u{A·h} disent combien de charges la batterie peut débiter, pas avec quelle poussée. C'est la tension qui apporte cette seconde information.",
        "**La relation.** $E = Q × U$, avec $Q$ en @u{A·h} et $U$ en @u{V} : le résultat sort directement en @u{W·h}.",
        "**Je remplace.** $E = 4{,}0 × 3{,}85$.",
        "**Je calcule.** $E = 15{,}4$ @u{W·h}.",
        "**Je vérifie l'ordre de grandeur.** Une quinzaine de wattheures pour un téléphone : c'est bien ce qu'on trouve sur le marché, et cela représente $15{,}4 × 3600 ≈ 55\u00a0000$ @u{J}."],
  indice:"Capacité en @u{A·h} multipliée par tension en @u{V} donne des @u{W·h} directement."},

 {id:"el14", niveau:3, type:"num", enonce:"Une batterie de vélo de $500$ @u{W·h} alimente un moteur consommant $200$ @u{W} en moyenne. Quelle autonomie, en heures ? (arrondis au dixième)",
  rep:2.5, tol:0.05, unite:"h",
  diag:[{v:100000, m:"Tu as multiplié l'énergie par la puissance. L'autonomie est une **durée** : on divise l'énergie disponible par la puissance consommée."},
        {v:0.4, m:"Tu as inversé la division ($@f{200}{500}$). Vérifie par les unités : des @u{W·h} divisés par des @u{W} donnent des heures."},
        {v:300, m:"Tu as calculé la différence $500 - 200$. Une soustraction entre une énergie et une puissance n'a pas de sens : ce sont deux grandeurs différentes."}],
  corr:["**Ce que dit l'énoncé.** Une réserve de $500$ @u{W·h} et une consommation de $200$ @u{W}. Ce qu'on cherche : combien de temps la réserve tient.",
        "**L'image qui guide.** Un réservoir de $500$ litres vidé à $200$ litres par heure tient deux heures et demie. C'est exactement le même calcul.",
        "**La relation.** autonomie $= @f{E}{P}$, l'énergie disponible divisée par la puissance consommée.",
        "**Je remplace.** $@f{500}{200}$.",
        "**Je calcule.** $2{,}5$ heures, soit deux heures et trente minutes.",
        "**Je vérifie par les unités, et par le réel.** Des @u{W·h} divisés par des @u{W} donnent bien des heures. Et en pratique on obtiendra un peu moins : une batterie ne se vide jamais entièrement, et le rendement n'est pas parfait."],
  indice:"Énergie disponible divisée par puissance consommée : le résultat est une durée."},

 {id:"el15", niveau:2, type:"num", unite:"Ω",
  enonce:"Le graphique ci-dessous est la caractéristique d'un dipôle : il donne la tension à ses bornes en fonction de l'intensité qui le traverse. Quelle est la valeur de sa résistance ?",
  fig:{titre:"Document — caractéristique U = f(I) d'un dipôle", vue:[-0.08,-2.4,0.62,12.5], w:410, h:250,
       libre:true, grille:false, axes:false, objets:[
    {t:"axes", x0:0, y0:0, ax:"I (A)", ay:"U (V)"},
    {t:"courbeXY", pts:[[0,0],[0.1,2],[0.3,6],[0.5,10]], couleur:"bleu", points:true},
    {t:"seg", de:[0.5,0], a:[0.5,10], couleur:"line2", pointille:true},
    {t:"seg", de:[0,10], a:[0.5,10], couleur:"line2", pointille:true},
    {t:"texte", x:0.1, y:-1.5, txt:"0,1", couleur:"ink3", taille:11},
    {t:"texte", x:0.3, y:-1.5, txt:"0,3", couleur:"ink3", taille:11},
    {t:"texte", x:0.5, y:-1.5, txt:"0,5", couleur:"ink3", taille:11},
    {t:"texte", x:-0.045, y:2, txt:"2", couleur:"ink3", taille:11},
    {t:"texte", x:-0.045, y:6, txt:"6", couleur:"ink3", taille:11},
    {t:"texte", x:-0.045, y:10, txt:"10", couleur:"ink3", taille:11}
   ], note:"Les points de mesure sont alignés et passent par l'origine : le dipôle est un conducteur ohmique."},
  rep:20, tol:0.5,
  diag:[{v:0.05, m:"Tu as calculé $@f{I}{U}$. La loi d'Ohm s'écrit $U = R I$, donc $R = @f{U}{I}$ : la tension au numérateur."},
        {v:10, m:"$10$ @u{V} est une tension lue sur le graphique, pas une résistance. Il reste à la diviser par l'intensité correspondante."},
        {v:5, m:"Tu as sans doute divisé $10$ par $2$. Il faut diviser la tension par **l'intensité du même point** : $@f{10}{0{,}5}$."}],
  corr:["**Ce que montre le document.** En abscisse l'intensité en ampères, en ordonnée la tension en volts. Chaque point est une mesure : on a fait varier $I$ et relevé $U$.",
        "**Première observation, avant tout calcul.** Les points sont **alignés** et la droite passe par **l'origine**. C'est la signature d'un conducteur ohmique : $U$ est proportionnelle à $I$.",
        "**L'outil.** La loi d'Ohm, $U = R × I$. La résistance est donc $R = @f{U}{I}$ — c'est la pente de la droite.",
        "**Étape 1 — je choisis un point bien lisible.** Le dernier, tout à droite : $I = 0{,}5$ @u{A} et $U = 10$ @u{V}. Les pointillés le repèrent sur les deux axes.",
        "**Étape 2 — je divise.** $R = @f{10}{0{,}5} = 20$ @u{Ω}.",
        "**Le contrôle, et pourquoi il compte.** Reprenons avec un autre point : $@f{6}{0{,}3} = 20$ @u{Ω}, et $@f{2}{0{,}1} = 20$ @u{Ω}. Les trois points donnent la même valeur — c'est bien ce qu'annonçait l'alignement. Si un point avait donné autre chose, le dipôle n'aurait pas été ohmique, et parler d'« une » résistance n'aurait plus eu de sens."],
  indice:"Choisis un point de la droite, lis ses deux coordonnées, et applique $R = @f{U}{I}$."}
]
},

/* ======== 10. TRAVAIL ET ÉNERGIE MÉCANIQUE ======== */
{
id:"mecanique", n:11, titre:"Travail et énergie mécanique",
sous:"Compter l'énergie plutôt que suivre le mouvement",
desc:"Travail d'une force, énergie cinétique, énergie potentielle de pesanteur, conservation de l'énergie mécanique.",
duree:40,
sections:[
 {titre:"Le travail d'une force", blocs:[
  {t:"idee", x:"Une force ne « donne » de l'énergie à un objet que si celui-ci **se déplace**. Le **travail** mesure l'énergie transférée par une force au cours d'un déplacement."},
  {t:"p", x:"Le mot est trompeur : tenir un sac lourd à bout de bras fatigue énormément, mais si le sac ne bouge pas, le travail de la force est **nul** au sens de la physique. Sans déplacement, pas de transfert d'énergie."},
  {t:"formule", titre:"Travail d'une force constante",
   x:"$W = F × d × cos(α)$",
   note:"$W$ en @u{J} · $F$ en @u{N} · $d$ en @u{m} · $α$ est l'angle entre la force et le déplacement."},
  {t:"tbl", head:["Angle $α$","$cos(α)$","Travail","Nom"], rows:[
   ["$0°$ (force dans le sens du mouvement)","$1$","$W = F × d$, positif","**moteur**"],
   ["$90°$ (force perpendiculaire)","$0$","$W = 0$","nul"],
   ["$180°$ (force opposée au mouvement)","$-1$","$W = -F × d$, négatif","**résistant**"]
  ]},
  {t:"p", x:"Ces trois lignes suffisent presque toujours. Un travail **moteur** apporte de l'énergie à l'objet, qui accélère. Un travail **résistant** lui en retire, il ralentit — c'est le cas des frottements, toujours opposés au mouvement. Et une force perpendiculaire au déplacement ne transfère rien du tout : c'est pour cela que la réaction d'un support horizontal ne travaille jamais."}
  ,{t:"mots", items:[
   ["Travail ($W$, en @u{J})","L'énergie qu'une force transfère à un objet pendant son déplacement. Sans déplacement, pas de travail."],
   ["Travail moteur","Un travail positif : la force pousse dans le sens du mouvement et apporte de l'énergie."],
   ["Travail résistant","Un travail négatif : la force s'oppose au mouvement et retire de l'énergie. Les frottements, toujours."],
   ["Énergie cinétique ($E_c$)","L'énergie que possède un objet **parce qu'il bouge**. Elle dépend du carré de sa vitesse."],
   ["Énergie potentielle de pesanteur ($E_{pp}$)","L'énergie en réserve d'un objet **parce qu'il est en hauteur**. Elle se libère quand il tombe."],
   ["Énergie mécanique ($E_m$)","La somme des deux. Sans frottement, elle ne change pas de tout le mouvement."],
   ["Dissiper","Transformer de l'énergie mécanique en chaleur, sans possibilité de la récupérer. C'est ce que font les frottements."]
  ]},
  {t:"exemple", titre:"Exemple guidé — trois travaux à comparer", enonce:"Une caisse de $20$ @u{kg} est tirée horizontalement sur $5{,}0$ @u{m} par une force horizontale de $80$ @u{N}. Une force de frottement de $30$ @u{N} s'y oppose. Calculer le travail de chaque force. On prend $g = 9{,}81$ @u{N/kg}.", etapes:[
   {q:"La force de traction", r:"Elle est dans le sens du déplacement, donc $α = 0°$ : $W = 80 × 5{,}0 × 1 = 400$ @u{J}. Travail moteur."},
   {q:"Le frottement", r:"Il est opposé au déplacement, donc $α = 180°$ : $W = 30 × 5{,}0 × (-1) = -150$ @u{J}. Travail résistant."},
   {q:"Le poids", r:"Il est vertical, le déplacement est horizontal : $α = 90°$, donc $W = 0$ @u{J}. Le poids ne travaille pas ici."},
   {q:"La réaction du sol", r:"Perpendiculaire au déplacement elle aussi : $W = 0$ @u{J}."},
   {q:"Le bilan", r:"Travail total : $400 - 150 = 250$ @u{J}. C'est l'énergie réellement apportée à la caisse, qui va donc accélérer."}
  ]}
 ]},

 {titre:"L'énergie cinétique : celle du mouvement", blocs:[
  {t:"formule", titre:"Énergie cinétique",
   x:"$E_c = @f{1}{2} × m × v^2$",
   note:"$E_c$ en @u{J} · $m$ en @u{kg} · $v$ en @u{m/s}. La vitesse est **au carré** : c'est ce qui rend cette formule si importante."},
  {t:"p", x:"Le carré de la vitesse a une conséquence que tout conducteur devrait connaître : rouler deux fois plus vite ne double pas l'énergie à dissiper au freinage, il la **quadruple**. À $100$ @u{km/h}, une voiture emporte quatre fois plus d'énergie qu'à $50$ @u{km/h} — d'où des distances de freinage quatre fois plus longues, et des chocs incomparablement plus violents."},
  {t:"fig", titre:"L'énergie cinétique croît comme le carré de la vitesse",
   vue:[0,0,5.4,1.15], w:400, h:250, libre:true, grille:false, axes:false,
   objets:[
    {t:"axes", x0:0, y0:0, ax:"vitesse v", ay:"Ec"},
    {t:"courbeXY", couleur:"bleu", pts:[[0,0],[0.5,0.01],[1,0.04],[1.5,0.09],[2,0.16],[2.5,0.25],[3,0.36],[3.5,0.49],[4,0.64],[4.5,0.81],[5,1.0]]},
    {t:"seg", de:[2.5,0], a:[2.5,0.25], couleur:"line2", pointille:true},
    {t:"seg", de:[5,0], a:[5,1.0], couleur:"line2", pointille:true},
    {t:"texte", x:2.5, y:0.33, txt:"v", couleur:"ink3"},
    {t:"texte", x:4.55, y:1.07, txt:"2v → 4 fois plus", couleur:"rouge", taille:12}
   ],
   note:"La courbe s'envole : c'est pourquoi les excès de vitesse sont si dangereux."},
  {t:"formule", titre:"Théorème de l'énergie cinétique",
   x:"$ΔE_c = Σ W$",
   note:"La variation d'énergie cinétique est égale à la somme des travaux de toutes les forces."},
  {t:"p", x:"Ce théorème est un outil de comptable : il ne demande pas de suivre le mouvement instant par instant, seulement de comparer un état de départ et un état d'arrivée. Beaucoup de problèmes qui paraissent compliqués s'y résolvent en trois lignes."},
  {t:"check", q:"Une voiture roule deux fois plus vite. Par combien son énergie cinétique est-elle multipliée ?",
   choix:["4","2","8","1, elle ne change pas"], bonne:0,
   expl:["Exact : la vitesse est au carré dans $E_c = @f{1}{2}mv^2$. Doubler $v$ multiplie $v^2$ par $2^2 = 4$.",
         "Ce serait le cas si la vitesse intervenait simplement, sans carré. Or elle est élevée au carré.",
         "8 correspondrait au cube de 2. La formule fait intervenir un carré, pas un cube.",
         "L'énergie cinétique dépend directement de la vitesse : elle change forcément."]}
 ]},

 {titre:"L'énergie potentielle de pesanteur : celle de la hauteur", blocs:[
  {t:"formule", titre:"Énergie potentielle de pesanteur",
   x:"$E_{pp} = m × g × z$",
   note:"$z$ est l'altitude, mesurée à partir d'une origine que **l'on choisit**. Seules les différences d'altitude comptent."},
  {t:"p", x:"Cette énergie est dite « potentielle » parce qu'elle est en réserve : un objet en hauteur ne possède aucune énergie de mouvement, mais il en acquerra dès qu'on le lâchera. L'énergie est là, en attente."},
  {t:"astuce", titre:"L'origine des altitudes se choisit librement", x:"On peut placer le zéro au sol, sur la table, ou à n'importe quelle hauteur : cela change la valeur de $E_{pp}$, mais **jamais** sa variation entre deux points. Comme seules les variations interviennent dans les bilans, on choisit toujours l'origine qui simplifie les calculs — en général le point le plus bas."}
 ]},

 {titre:"L'énergie mécanique et sa conservation", blocs:[
  {t:"idee", x:"L'**énergie mécanique** est la somme des deux précédentes. En l'absence de frottements, elle **ne change pas** : l'énergie passe d'une forme à l'autre sans jamais se perdre."},
  {t:"formule", titre:"Énergie mécanique", x:"$E_m = E_c + E_{pp}$", note:"Sans frottements : $E_m$ est constante. Avec frottements : elle diminue."},
  {t:"fig", titre:"Une bille qui descend : l'énergie change de forme",
   vue:[0,0,10,5.5], w:440, h:250, grille:false, axes:false,
   objets:[
    {t:"courbeXY", couleur:"ink3", epais:3, pts:[[0.6,4.6],[1.6,4.3],[2.6,3.5],[3.6,2.4],[4.6,1.4],[5.6,0.8],[7,0.6],[9,0.6]]},
    {t:"cercle", c:[0.9,4.75], r:0.22, couleur:"bleu", remplir:true},
    {t:"cercle", c:[8.2,0.82], r:0.22, couleur:"bleu", remplir:true},
    {t:"seg", de:[0.6,0.6], a:[9.4,0.6], couleur:"line2", pointille:true},
    {t:"vec", de:[1.3,4.6], a:[1.3,0.7], couleur:"ambre"},
    {t:"texte", x:2.2, y:2.7, txt:"hauteur h", couleur:"ambre", taille:12},
    {t:"texte", x:1.1, y:5.2, txt:"Ec = 0, Epp max", couleur:"vert", taille:11.5},
    {t:"texte", x:8.1, y:1.5, txt:"Ec max, Epp = 0", couleur:"vert", taille:11.5}
   ],
   note:"En haut, toute l'énergie est en réserve. En bas, elle est entièrement passée en mouvement."},
  {t:"exemple", titre:"Exemple guidé — la vitesse au bas d'une pente", enonce:"Une bille part sans vitesse d'une hauteur $h = 1{,}8$ @u{m} et glisse sans frottement. Quelle est sa vitesse en bas ? On prend $g = 9{,}81$ @u{N/kg}.", etapes:[
   {q:"Choisir l'origine des altitudes", r:"Je la place en bas : ainsi $E_{pp} = 0$ à l'arrivée, ce qui simplifie tout."},
   {q:"Écrire l'énergie mécanique au départ", r:"La bille est immobile : $E_c = 0$. Donc $E_m = E_{pp} = m g h$."},
   {q:"Écrire l'énergie mécanique à l'arrivée", r:"L'altitude est nulle : $E_{pp} = 0$. Donc $E_m = E_c = @f{1}{2} m v^2$."},
   {q:"Égaler, puisqu'il n'y a pas de frottement", r:"$@f{1}{2} m v^2 = m g h$. La masse se simplifie des deux côtés — la vitesse ne dépend donc pas de la masse !"},
   {q:"Isoler la vitesse", r:"$v^2 = 2 g h = 2 × 9{,}81 × 1{,}8 ≈ 35{,}3$, donc $v = @r{35{,}3} ≈ 5{,}9$ @u{m/s}."},
   {q:"Ce qu'il faut retenir", r:"La masse disparaît du résultat : une bille lourde et une bille légère arrivent en bas à la même vitesse. C'est l'expérience de Galilée, retrouvée par un simple bilan d'énergie."}
  ]},
  {t:"formule", titre:"Le raccourci de la chute libre", x:"$v = @r{2 g h}$", note:"Valable pour un objet parti sans vitesse initiale, sans frottement. La masse n'intervient pas."}
  ,{t:"figi", nom:"energie"}
  ,{t:"p", x:"Fais descendre la bille et surveille la **barre verte**. Sans frottement, elle ne bouge pas d'un pixel : l'énergie ne fait que passer de la réserve (en ambre) au mouvement (en bleu). Monte ensuite le curseur de frottement : la barre verte se met à descendre, et l'écart avec le trait rouge mesure exactement ce qui est parti en chaleur."}
  ,{t:"methode", titre:"Résoudre un problème par l'énergie", etapes:[
   "**Choisir deux instants** : celui de départ et celui d'arrivée. On ne s'occupe pas de ce qui se passe entre les deux — c'est tout l'intérêt de la méthode.",
   "**Placer l'origine des altitudes** au point le plus bas : ainsi $E_{pp} = 0$ à cet endroit, et les calculs se simplifient.",
   "**Écrire l'énergie mécanique à chaque instant** : $E_m = E_c + E_{pp}$, en remplaçant par 0 tout ce qui est nul (vitesse nulle au départ, altitude nulle à l'arrivée).",
   "**Égaler les deux s'il n'y a pas de frottement.** S'il y en a, leur différence donne exactement l'énergie dissipée.",
   "**Isoler l'inconnue.** Si c'est une vitesse, ne pas oublier la racine carrée à la fin."
  ], exemple:"Une bille lâchée de $5{,}0$ @u{m} : au départ $E_m = m g h$, à l'arrivée $E_m = @f{1}{2} m v^2$. La masse se simplifie, donc $v = @r{2 × 9{,}81 × 5{,}0} ≈ 9{,}9$ @u{m/s}."}

  ,{t:"check", q:"Sur un toboggan sans frottement, de quoi dépend la vitesse en bas ?",
   choix:["Seulement de la hauteur de départ","De la masse de l'enfant","De la longueur du toboggan","De la pente du toboggan"], bonne:0,
   expl:["Exact : $v = @r{2gh}$. Ni la masse, ni la forme du toboggan n'apparaissent — seule compte la dénivelée.",
         "La masse se simplifie dans le calcul : elle est des deux côtés de l'égalité. Un enfant lourd et un enfant léger arrivent à la même vitesse.",
         "Un toboggan long et doux ou court et raide, peu importe : c'est la **hauteur** perdue qui compte, pas le chemin parcouru.",
         "La pente change la durée de la descente, pas la vitesse d'arrivée. C'est justement ce que la méthode énergétique rend évident."]}
 ]},

 {titre:"Quand les frottements entrent en jeu", blocs:[
  {t:"p", x:"Dans la réalité, l'énergie mécanique diminue toujours un peu : les frottements en convertissent une partie en chaleur. Cette énergie n'est pas détruite — elle a simplement quitté le domaine mécanique."},
  {t:"formule", titre:"Bilan avec frottements",
   x:"$E_{m,final} - E_{m,initial} = W_{frottements}$",
   note:"Ce travail est toujours **négatif** : les frottements retirent de l'énergie au système."},
  {t:"exemple", titre:"Exemple guidé — combien les frottements ont-ils pris ?", enonce:"Un skieur de $70$ @u{kg} descend $20$ @u{m} de dénivelé et arrive à $15$ @u{m/s}. Il partait sans vitesse. Quelle énergie les frottements ont-ils dissipée ? On prend $g = 9{,}81$ @u{N/kg}.", etapes:[
   {q:"L'énergie disponible au départ", r:"$E_{pp} = m g h = 70 × 9{,}81 × 20 ≈ 13 700$ @u{J}."},
   {q:"L'énergie de mouvement à l'arrivée", r:"$E_c = @f{1}{2} m v^2 = 0{,}5 × 70 × 15^2 = 0{,}5 × 70 × 225 ≈ 7 900$ @u{J}."},
   {q:"Comparer", r:"Il manque $13 700 - 7 900 = 5 800$ @u{J} : l'énergie mécanique a diminué."},
   {q:"Conclure", r:"Ces $5{,}8$ @u{kJ} ont été dissipés par les frottements de la neige et de l'air, sous forme de chaleur."},
   {q:"Le contrôle", r:"Sans frottement, il serait arrivé à $v = @r{2 × 9{,}81 × 20} ≈ 19{,}8$ @u{m/s}. Il n'atteint que $15$ @u{m/s} : cohérent avec des frottements bien réels."}
  ]},
  {t:"piege", titre:"L'énergie ne disparaît jamais", x:"Dire « l'énergie a été perdue » est un raccourci de langage. Elle a été **convertie** en chaleur, en bruit, en usure. Le principe de conservation de l'énergie n'est jamais mis en défaut : c'est seulement l'énergie **mécanique** qui diminue."}
 ]},

 {titre:"La puissance : le travail rapporté au temps", blocs:[
  {t:"idee", x:"Monter cinq étages avec un sac de courses en marchant, ou monter les mêmes cinq étages avec le même sac en courant : le travail fourni est **exactement le même**, parce que la masse et la hauteur n'ont pas changé. Ce qui change, c'est le **temps** qu'on y met. La puissance est la grandeur inventée pour mesurer cette différence-là."},
  {t:"formule", titre:"Puissance moyenne",
   x:"$P = @f{W}{Δt}$",
   note:"$P$ en @u{W} (watt) · $W$ en @u{J} · $Δt$ en @u{s}. Un watt, c'est **un joule fourni chaque seconde**."},
  {t:"p", x:"Cette définition explique une phrase que l'on entend souvent sans y penser : une ampoule de $60$ @u{W} ne « contient » pas $60$ joules. Elle en **consomme** $60$ à chaque seconde. Laissée allumée une minute, elle en a consommé $3600$ ; une heure, $216 000$. La puissance est un débit, l'énergie est un total — exactement comme le débit d'un robinet et le volume du seau."},
  {t:"formule", titre:"Le lien dans l'autre sens",
   x:"$W = P × Δt$",
   note:"C'est la même relation, retournée. On l'utilise dès qu'une puissance est donnée et qu'on cherche une énergie."},
  {t:"p", x:"Il existe une seconde écriture de la puissance, très commode dès qu'un objet avance à vitesse constante. Partons du travail d'une force qui tire dans le sens du mouvement : $W = F × d$. Divisons les deux côtés par la durée : $@f{W}{Δt} = F × @f{d}{Δt}$. Or $@f{d}{Δt}$ n'est rien d'autre que la vitesse. D'où :"},
  {t:"formule", titre:"Puissance d'une force qui tire dans le sens du mouvement",
   x:"$P = F × v$",
   note:"$P$ en @u{W} · $F$ en @u{N} · $v$ en @u{m/s}. Valable pour une force parallèle au déplacement et de même sens."},
  {t:"astuce", titre:"Ce que cette formule dit d'un vélo", x:"Un cycliste ne peut développer qu'une puissance limitée — disons $200$ @u{W} pendant une heure. Si $P$ est fixée, alors $F = @f{P}{v}$ : plus il va vite, moins il peut pousser fort. C'est précisément pour cela qu'il **change de vitesse** en côte : le dérailleur lui rend de la force en lui retirant de l'allure."},
  {t:"tbl", head:["Situation","Puissance, en ordre de grandeur"], rows:[
   ["Un élève qui monte un escalier","$150$ @u{W}"],
   ["Un cycliste amateur, en continu","$200$ @u{W}"],
   ["Un sprinteur cycliste, quelques secondes","$1500$ @u{W}"],
   ["Un ascenseur d'immeuble","$5$ @u{kW}"],
   ["Une voiture citadine","$60$ @u{kW}"],
   ["Une rame de TGV","$9$ @u{MW}"]
  ]},
  {t:"p", x:"Ce tableau sert de contrôle. Si un calcul de puissance humaine donne $20 000$ @u{W}, il y a une erreur quelque part : aucun être humain ne tient cette puissance. Si une puissance de moteur de voiture tombe à $60$ @u{W}, il manque un facteur mille."},
  {t:"exemple", titre:"Exemple guidé — la puissance d'un ascenseur", enonce:"Un ascenseur monte une cabine de $400$ @u{kg} sur $12$ @u{m} en $20$ @u{s}. Quelle puissance son moteur développe-t-il ? On prend $g = 9{,}81$ @u{N/kg}.", etapes:[
   {q:"Qu'est-ce qui est demandé : une énergie ou une puissance ?", r:"Une **puissance**, en watts. Mais une puissance se calcule toujours à partir d'une énergie : il faut donc commencer par l'énergie, même si elle n'est pas demandée."},
   {q:"Étape 1 — le travail à fournir", r:"Le moteur doit vaincre le poids sur $12$ @u{m} : $W = m g h = 400 × 9{,}81 × 12 ≈ 47 100$ @u{J}."},
   {q:"Étape 2 — la durée, en secondes", r:"$Δt = 20$ @u{s}. Elle est déjà en secondes : rien à convertir. Si l'énoncé avait dit « en une demi-minute », il aurait fallu écrire $30$ @u{s}."},
   {q:"Étape 3 — je divise", r:"$P = @f{W}{Δt} = @f{47 100}{20} ≈ 2360$ @u{W}, soit environ $2{,}4$ @u{kW}."},
   {q:"Le contrôle", r:"Le tableau des ordres de grandeur annonce quelques kilowatts pour un ascenseur : nous y sommes. Et l'on voit tout de suite ce que coûte la vitesse — monter la même cabine en $10$ @u{s} au lieu de $20$ demanderait $4700$ @u{W}, deux fois plus, pour exactement le même travail."}
  ]},
  {t:"methode", titre:"Calculer une puissance", etapes:[
   "**Lire l'unité demandée.** Des joules ? c'est une énergie. Des watts ? c'est une puissance. Cette seule lecture évite la moitié des erreurs.",
   "**Calculer d'abord l'énergie**, avec la formule qui convient : $W = F d$, $W = m g h$, $E_c = @f{1}{2} m v^2$…",
   "**Convertir la durée en secondes.** Une minute vaut $60$ @u{s}, une heure $3600$ @u{s}.",
   "**Diviser l'énergie par la durée**, et écrire l'unité @u{W}.",
   "**Comparer à un ordre de grandeur connu** : un humain, quelques centaines de watts ; une voiture, quelques dizaines de kilowatts."
  ]},
  {t:"piege", titre:"Le même symbole pour deux choses différentes", x:"En mécanique, $W$ est le **symbole du travail**, une énergie, qui se mesure en joules. Mais @u{W} est aussi le **symbole du watt**, l'unité de puissance. Écrire « $W = 2000$ @u{W} » n'a donc aucun sens. Repère-toi à la position : ce qui est **avant** le signe égal est une grandeur, ce qui suit le nombre est une unité."},
  {t:"piege", titre:"Diviser dans le bon sens", x:"La puissance est une énergie **par** seconde : l'énergie va au numérateur. Si tu obtiens un nombre minuscule comme $0{,}0004$ pour un moteur, tu as divisé à l'envers. Le contrôle est immédiat."},
  {t:"check", q:"Deux grues montent la même charge à la même hauteur. La première met $10$ @u{s}, la seconde $20$ @u{s}. Que peut-on dire ?",
   choix:["Même travail, mais la première développe une puissance deux fois plus grande","La première fournit deux fois plus de travail","La première fournit deux fois moins de travail","Les deux ont la même puissance"], bonne:0,
   expl:["Exact. Le travail ne dépend que de la masse et de la hauteur, identiques ici. C'est la **durée** qui change, donc la puissance : deux fois moins de temps, deux fois plus de puissance.",
         "Non : le travail vaut $m g h$. Ni la masse ni la hauteur ne changent, donc le travail non plus. Ce qui change, c'est le temps mis pour le fournir.",
         "Non plus, et pour la même raison : le travail est identique dans les deux cas. Aller plus vite ne demande pas **moins** de travail — cela demande **plus** de puissance.",
         "Si les puissances étaient égales, les deux grues mettraient le même temps. L'une va deux fois plus vite : sa puissance est donc double."]},
  {t:"check", q:"Un treuil tire un chariot avec une force de $250$ @u{N} à la vitesse constante de $2{,}0$ @u{m/s}. Quelle puissance développe-t-il ?",
   choix:["$500$ @u{W}","$125$ @u{W}","$250$ @u{W}","On ne peut pas savoir sans la durée"], bonne:0,
   expl:["Exact : $P = F × v = 250 × 2{,}0 = 500$ @u{W}. Cette écriture donne la puissance sans passer ni par la durée ni par la distance.",
         "$125$ @u{W}, c'est $@f{250}{2{,}0}$. Cette division sert à retrouver une **force** à partir d'une puissance. Ici la force est connue : il faut multiplier.",
         "$250$, c'est la force en newtons, pas la puissance. Une même force développe d'autant plus de puissance qu'elle tire vite : la vitesse doit entrer dans le calcul.",
         "C'est justement ce que $P = F × v$ permet d'éviter : ni la durée ni la distance ne sont nécessaires quand on connaît la force et la vitesse."]}
 ]},

 {titre:"Atelier — un toboggan qui frotte", blocs:[
  {t:"p", x:"Le raisonnement énergétique se résume à comparer un état de départ et un état d'arrivée. Cet atelier te le fait faire sur un cas où les frottements existent — donc sur un cas réel, et non sur le cas idéal des exercices d'entraînement."},
  {t:"atelier", titre:"Combien les frottements ont-ils pris ?",
   enonce:"Un enfant de $30$ @u{kg} part **sans vitesse** du haut d'un toboggan, à $3{,}0$ @u{m} de hauteur. Il arrive en bas à $6{,}0$ @u{m/s}. On prend $g = 9{,}81$ @u{N/kg}.",
   etapes:[
    {q:"Quelle énergie l'enfant possède-t-il au départ, en @u{J} ?",
     rep:883, tol:6, unite:"J",
     aide:"Au départ il ne bouge pas : toute son énergie vient de sa hauteur.",
     diag:[{v:540, m:"$540$ @u{J} est l'énergie **cinétique** de l'arrivée. Au départ, l'enfant est immobile : son énergie cinétique est nulle."},
           {v:90, m:"Tu as multiplié la masse par la hauteur en oubliant $g$. La formule est $E_{pp} = m g h$."},
           {v:30, m:"$30$ @u{kg} est la masse. L'énergie potentielle vaut $m g h$."}],
     expl:"$E_{pp} = m g h = 30 × 9{,}81 × 3{,}0 ≈ 883$ @u{J}. **Pourquoi rien d'autre.** L'enfant part sans vitesse : son énergie cinétique vaut zéro. Toute son énergie mécanique est donc en réserve, sous forme d'énergie de position. C'est le sens du mot « potentielle » : disponible, mais pas encore utilisée."},

    {q:"Quelle énergie possède-t-il à l'arrivée, en bas, en @u{J} ?",
     rep:540, tol:4, unite:"J",
     aide:"En bas, la hauteur est nulle. Il ne reste que l'énergie du mouvement.",
     diag:[{v:180, m:"Tu as oublié d'élever la vitesse au carré : $E_c = @f{1}{2} m v^2$, et $6{,}0^2 = 36$."},
           {v:1080, m:"Tu as oublié le facteur $@f{1}{2}$. $0{,}5 × 30 × 36 = 540$ @u{J}."},
           {v:883, m:"$883$ @u{J} est l'énergie du départ. On demande celle de l'arrivée, qui est cinétique."}],
     expl:"$E_c = @f{1}{2} m v^2 = 0{,}5 × 30 × 6{,}0^2 = 0{,}5 × 30 × 36 = 540$ @u{J}. **L'ordre des opérations compte.** Le carré ne porte que sur la vitesse : on calcule $36$ d'abord, jamais $(0{,}5 × 6)^2$. Et en bas, la hauteur étant nulle, l'énergie potentielle l'est aussi : il ne reste que le mouvement."},

    {q:"Quelle énergie les frottements ont-ils dissipée pendant la descente, en @u{J} ?",
     rep:343, tol:8, unite:"J",
     aide:"Compare ce qu'il avait au départ et ce qu'il a à l'arrivée. Où est passée la différence ?",
     diag:[{v:1423, m:"Tu as additionné les deux énergies. C'est leur **différence** qui mesure ce qui a été perdu."},
           {v:540, m:"$540$ @u{J} est l'énergie d'arrivée, pas ce qui manque."},
           {v:883, m:"$883$ @u{J} est l'énergie de départ. Ce qui a été dissipé est ce qui n'est pas arrivé en bas."}],
     expl:"$883 - 540 = 343$ @u{J} ont été dissipés. **Ce que « perdu » veut dire.** Ces $343$ joules n'ont pas disparu : ils ont chauffé le toboggan, le short de l'enfant et l'air alentour — c'est d'ailleurs pourquoi on se brûle parfois sur un toboggan métallique. L'énergie totale se conserve toujours ; c'est l'énergie **mécanique** qui diminue, parce qu'une partie a quitté le domaine du mouvement."},

    {q:"À quelle vitesse serait-il arrivé s'il n'y avait eu aucun frottement, en @u{m/s} ?",
     rep:7.67, tol:0.15, unite:"m/s",
     aide:"Sans frottement, toute l'énergie de hauteur devient de l'énergie de mouvement. Il existe un raccourci qui évite de passer par les joules.",
     diag:[{v:58.9, m:"$58{,}9$ est la valeur de $2 g h$, sous la racine. Il reste à en prendre la racine carrée."},
           {v:6, m:"$6{,}0$ @u{m/s} est la vitesse **réellement** atteinte, avec les frottements. Sans eux, elle serait plus grande."},
           {v:29.4, m:"Tu as calculé $g × 3{,}0$. La formule de la chute est $v = @r{2 g h}$, avec une racine."}],
     expl:"$v = @r{2 g h} = @r{2 × 9{,}81 × 3{,}0} = @r{58{,}9} ≈ 7{,}7$ @u{m/s}. **Ce que ce nombre prouve.** Il est plus grand que les $6{,}0$ @u{m/s} observés, et c'est heureux : sans frottement, l'enfant irait forcément plus vite. Si tu avais trouvé une valeur **inférieure** à $6{,}0$, ton calcul serait faux, sans même avoir à le relire. C'est le genre de contrôle qui vaut mieux qu'une relecture."},

    {q:"Un enfant deux fois plus lourd descendrait le même toboggan sans frottement. Sa vitesse en bas serait…",
     choix:["la même, la masse n'intervient pas","deux fois plus grande","deux fois plus petite","quatre fois plus grande"],
     bonne:0,
     diag:["","Il aurait deux fois plus d'énergie de hauteur, mais il faut aussi deux fois plus d'énergie pour le lancer à la même vitesse. Les deux se compensent.",
           "Être plus lourd ne ralentit pas : c'est l'intuition qui trompe, comme pour la chute libre.",
           "Ni quatre, ni deux : exactement la même. Regarde la formule $v = @r{2gh}$ — la masse n'y figure pas."],
     expl:"La vitesse serait exactement la même. **Pourquoi la masse s'en va, une fois de plus.** Écrivons la conservation : $@f{1}{2} m v^2 = m g h$. Le $m$ est présent des deux côtés, on le simplifie, et il reste $v = @r{2 g h}$ — sans masse. C'est le même phénomène qu'en chute libre : un corps plus lourd emmagasine plus d'énergie en hauteur, mais il en faut d'autant plus pour le mettre en mouvement."}
   ],
   bilan:"La méthode énergétique tient en une phrase : **on compare un état de départ et un état d'arrivée, sans jamais se demander ce qui s'est passé entre les deux**. La forme du toboggan, sa longueur, ses virages n'ont joué aucun rôle dans ce calcul — seules comptaient la hauteur perdue et la vitesse gagnée."}
 ]},

 {titre:"Récapitulatif", blocs:[
  {t:"tbl", head:["La question ressemble à…","Ce qu'il faut faire"], rows:[
   ["« Travail de cette force ? »","$W = F d cos(α)$ ; regarder l'angle avant tout"],
   ["« Le poids travaille-t-il ? »","Non si le déplacement est horizontal"],
   ["« Vitesse en bas d'une pente sans frottement ? »","$v = @r{2gh}$, la masse n'intervient pas"],
   ["« Énergie dissipée par les frottements ? »","$E_{m,final} - E_{m,initial}$, résultat négatif"],
   ["« La vitesse double, et l'énergie ? »","Multipliée par 4"],
   ["« Quelle puissance ? »","Calculer l'énergie, puis diviser par la durée en secondes"]
  ]},
  {t:"liste", items:[
   "**La méthode énergétique évite de suivre le mouvement** : on compare seulement un état de départ et un état d'arrivée.",
   "**Sans frottement**, $E_m$ se conserve : ce que l'on perd en hauteur, on le gagne en vitesse.",
   "**Avec frottement**, $E_m$ diminue, et la différence mesure exactement l'énergie dissipée."
  ]},
  {t:"idee", x:"En haut d'une pente, l'énergie est en réserve. En bas, elle est en mouvement. Entre les deux, rien ne s'est créé ni perdu — tout s'est transformé."}
 ]}
],
exos:[
 {id:"mc1", niveau:1, type:"num", enonce:"Quelle est l'énergie cinétique d'une voiture de $1200$ @u{kg} roulant à $20$ @u{m/s} ? Réponds en @u{kJ}.",
  rep:240, tol:1, unite:"kJ",
  diag:[{v:12000, m:"Tu as oublié d'élever la vitesse au carré, ou de multiplier par $@f{1}{2}$. La formule est $E_c = @f{1}{2}mv^2$."},
        {v:480, m:"Tu as oublié le facteur $@f{1}{2}$. $E_c = 0{,}5 × 1200 × 400 = 240 000$ @u{J}."},
        {v:240000, m:"C'est le bon résultat, mais en joules. La question demande des kilojoules : $240 000$ @u{J} $= 240$ @u{kJ}."}],
  corr:["**Ce que dit l'énoncé.** Une voiture de $1200$ @u{kg} roulant à $20$ @u{m/s}. On cherche son énergie cinétique, en kilojoules.",
        "**Ce qu'est l'énergie cinétique.** L'énergie que possède un objet **parce qu'il bouge**. Elle s'écrit $E_c = @f{1}{2} m v^2$.",
        "**Étape 1 — le carré de la vitesse, d'abord.** $20^2 = 400$. C'est l'opération à faire en premier : le carré ne porte que sur $v$.",
        "**Étape 2 — je multiplie par la masse.** $1200 × 400 = 480 000$.",
        "**Étape 3 — je prends la moitié.** $E_c = 0{,}5 × 480 000 = 240 000$ @u{J}.",
        "**Étape 4 — je convertis.** $240 000$ @u{J} $= 240$ @u{kJ}, puisqu'un kilojoule vaut mille joules. À $40$ @u{m/s}, la même voiture emporterait $960$ @u{kJ} : quatre fois plus, pour une vitesse seulement doublée."],
  indice:"Élève d'abord la vitesse au carré, puis n'oublie pas le facteur $@f{1}{2}$ — et convertis en @u{kJ}."},

 {id:"mc2", niveau:1, type:"num", enonce:"Un sac de $5{,}0$ @u{kg} est monté de $3{,}0$ @u{m}. De combien son énergie potentielle de pesanteur augmente-t-elle, en @u{J} ? On prend $g = 9{,}81$ @u{N/kg}.",
  rep:147, tol:1, unite:"J",
  diag:[{v:15, m:"Tu as multiplié la masse par la hauteur en oubliant $g$. La formule est $E_{pp} = m × g × z$."},
        {v:1.7, m:"Tu as divisé au lieu de multiplier. L'énergie potentielle est un produit des trois grandeurs."},
        {v:49, m:"Tu as oublié un facteur : $5{,}0 × 9{,}81 = 49$, il reste à multiplier par la hauteur $3{,}0$ @u{m}."}],
  corr:["**Ce que dit l'énoncé.** Un sac de $5{,}0$ @u{kg} monté de $3{,}0$ @u{m}, avec $g = 9{,}81$ @u{N/kg}.",
        "**Ce qu'est l'énergie potentielle de pesanteur.** L'énergie mise **en réserve** par la hauteur. Un objet en hauteur ne bouge pas, mais il libérera cette énergie dès qu'il tombera.",
        "**La formule.** $E_{pp} = m × g × z$ : trois facteurs à multiplier, sans en oublier aucun.",
        "**Je remplace.** $E_{pp} = 5{,}0 × 9{,}81 × 3{,}0$.",
        "**Je calcule par étapes.** $5{,}0 × 9{,}81 = 49{,}05$, puis $49{,}05 × 3{,}0 ≈ 147$ @u{J}.",
        "**J'interprète.** Ces $147$ @u{J} sont exactement l'énergie qu'il a fallu fournir pour monter le sac — et exactement celle qu'il restituerait en retombant de la même hauteur."],
  indice:"Trois facteurs à multiplier : la masse, $g$, et la hauteur."},

 {id:"mc3", niveau:2, type:"num", enonce:"Une caisse est tirée sur $8{,}0$ @u{m} par une force horizontale de $50$ @u{N}, dans le sens du déplacement. Quel est le travail de cette force, en @u{J} ?",
  rep:400, tol:1, unite:"J",
  diag:[{v:6.25, m:"Tu as divisé la force par la distance. Le travail est un produit : $W = F × d$ quand la force est dans le sens du déplacement."},
        {v:58, m:"Tu as additionné force et distance. Ces deux grandeurs ne s'additionnent pas : elles se multiplient."},
        {v:-400, m:"Le signe est faux. La force est **dans le sens** du déplacement : l'angle vaut $0°$, son cosinus vaut $+1$, le travail est moteur donc positif."}],
  corr:["**Ce que dit l'énoncé.** Une force de $50$ @u{N}, **dans le sens du déplacement**, sur $8{,}0$ @u{m}.",
        "**Ce qu'est le travail.** L'énergie transférée par une force pendant un déplacement. Sans déplacement, pas de travail — même si l'on se fatigue.",
        "**La formule générale.** $W = F × d × cos(α)$, où $α$ est l'angle entre la force et le déplacement.",
        "**Étape 1 — je détermine l'angle.** La force est dans le sens du déplacement : $α = 0°$, et $cos(0°) = 1$. La formule se réduit à $W = F × d$.",
        "**Étape 2 — je calcule.** $W = 50 × 8{,}0 = 400$ @u{J}.",
        "**J'interprète le signe.** Le résultat est positif : le travail est **moteur**. La force apporte $400$ @u{J} à la caisse, qui accélère. Si la force avait été opposée au mouvement, on aurait trouvé $-400$ @u{J}."],
  indice:"Force dans le sens du déplacement : le cosinus vaut 1."},

 {id:"mc4", niveau:2, type:"qcm", enonce:"Une personne porte une valise à bout de bras et marche horizontalement sur $20$ @u{m}. Quel est le travail de la force qu'elle exerce verticalement sur la valise ?",
  choix:["Nul, car la force est perpendiculaire au déplacement","Positif, car elle se fatigue","Négatif, car elle lutte contre le poids","Impossible à dire sans connaître la masse"], bonne:0,
  diag:["",
        "La fatigue physiologique n'est pas le travail au sens de la physique. Les muscles se contractent en permanence et consomment de l'énergie, mais aucune énergie n'est transférée **à la valise**, qui ne monte ni ne descend.",
        "Elle lutte bien contre le poids, mais sans déplacement vertical : l'énergie transférée à la valise est nulle. Un travail résistant supposerait un déplacement opposé à la force.",
        "La masse n'y change rien : quel que soit son poids, l'angle reste de $90°$ et le cosinus reste nul."],
  corr:["**Ce que dit l'énoncé.** Une personne porte une valise à bout de bras et marche horizontalement sur $20$ @u{m}.",
        "**Étape 1 — quelle est la direction de la force ?** Pour soutenir la valise, la main exerce une force **verticale**, dirigée vers le haut.",
        "**Étape 2 — quelle est la direction du déplacement ?** **Horizontale** : la personne avance, la valise ne monte ni ne descend.",
        "**Étape 3 — l'angle entre les deux.** Une verticale et une horizontale font un angle de $90°$. Or $cos(90°) = 0$.",
        "**Étape 4 — j'applique la formule.** $W = F × d × cos(90°) = F × d × 0 = 0$ @u{J}.",
        "**Je lève le paradoxe.** Se fatiguer et travailler au sens de la physique sont deux choses différentes. Les muscles se contractent et consomment de l'énergie, mais **aucune énergie n'est transférée à la valise** : elle reste exactement à la même hauteur."],
  indice:"Regarde l'angle entre la direction de la force et celle du déplacement."},

 {id:"mc5", niveau:2, type:"num", enonce:"Une bille est lâchée sans vitesse d'une hauteur de $5{,}0$ @u{m}, sans frottement. Quelle est sa vitesse en arrivant au sol, en @u{m/s} ? On prend $g = 9{,}81$ @u{N/kg}.",
  rep:9.9, tol:0.15, unite:"m/s",
  diag:[{v:49.05, m:"Tu as calculé $g × h$ sans multiplier par 2 ni prendre la racine. La formule est $v = @r{2 g h}$."},
        {v:98.1, m:"Tu as calculé $2 g h$ mais oublié la racine carrée. Ce résultat est $v^2$, pas $v$."},
        {v:7, m:"Tu as pris la racine de $2h$ ou d'une autre combinaison. Reprends : $2 × 9{,}81 × 5{,}0 = 98{,}1$, puis $@r{98{,}1} ≈ 9{,}9$."}],
  corr:["**Ce que dit l'énoncé.** Une bille lâchée **sans vitesse** de $5{,}0$ @u{m}, sans frottement, avec $g = 9{,}81$ @u{N/kg}.",
        "**La méthode énergétique.** Plutôt que de suivre la chute instant par instant, je compare seulement le départ et l'arrivée.",
        "**Étape 1 — l'énergie au départ.** La bille est immobile, donc $E_c = 0$. Toute son énergie est en réserve : $E_m = m g h$.",
        "**Étape 2 — l'énergie à l'arrivée.** Elle est au sol, donc $E_{pp} = 0$ si j'y place l'origine. Toute l'énergie est passée en mouvement : $E_m = @f{1}{2} m v^2$.",
        "**Étape 3 — j'égale, puisqu'il n'y a pas de frottement.** $@f{1}{2} m v^2 = m g h$. La masse apparaît des deux côtés : elle se simplifie. Donc $v^2 = 2 g h$.",
        "**Étape 4 — je calcule.** $v^2 = 2 × 9{,}81 × 5{,}0 = 98{,}1$, puis $v = @r{98{,}1} ≈ 9{,}9$ @u{m/s}, soit environ $36$ @u{km/h}. Ne pas oublier la racine : $98{,}1$ est $v^2$, pas $v$."],
  indice:"$v = @r{2gh}$ — n'oublie pas la racine carrée à la fin."},

 {id:"mc6", niveau:3, type:"num", enonce:"Un skieur de $60$ @u{kg} descend $15$ @u{m} de dénivelé en partant sans vitesse, et arrive à $12$ @u{m/s}. Quelle énergie a été dissipée par les frottements, en @u{J} ? On prend $g = 9{,}81$ @u{N/kg}.",
  rep:4509, tol:30, unite:"J",
  diag:[{v:8829, m:"$8829$ @u{J} est l'énergie potentielle de départ. Il faut lui retrancher l'énergie cinétique effectivement acquise à l'arrivée."},
        {v:4320, m:"$4320$ @u{J} est l'énergie cinétique à l'arrivée. La question porte sur ce qui **manque** par rapport à l'énergie de départ."},
        {v:13149, m:"Tu as additionné les deux énergies au lieu de les soustraire. L'énergie dissipée est la différence entre celle de départ et celle d'arrivée."}],
  corr:["**Ce que dit l'énoncé.** Un skieur de $60$ @u{kg} descend $15$ @u{m} de dénivelé sans vitesse initiale, et arrive à $12$ @u{m/s}.",
        "**L'idée.** Sans frottement, toute l'énergie de hauteur se retrouverait en énergie de mouvement. Ce qui manque à l'arrivée mesure exactement ce que les frottements ont pris.",
        "**Étape 1 — l'énergie mécanique au départ.** Immobile, donc $E_c = 0$. Reste $E_{pp} = m g h = 60 × 9{,}81 × 15 ≈ 8829$ @u{J}.",
        "**Étape 2 — l'énergie mécanique à l'arrivée.** En bas, donc $E_{pp} = 0$. Reste $E_c = @f{1}{2} m v^2 = 0{,}5 × 60 × 12^2 = 0{,}5 × 60 × 144 = 4320$ @u{J}.",
        "**Étape 3 — je compare.** $8829 - 4320 = 4509$ @u{J} ont disparu du bilan mécanique.",
        "**Je conclus et je vérifie.** Ces $4509$ @u{J} ont été dissipés en chaleur par la neige et l'air. Contrôle : sans frottement il serait arrivé à $@r{2 × 9{,}81 × 15} ≈ 17{,}2$ @u{m/s}, bien plus que les $12$ @u{m/s} observés. Cohérent."],
  indice:"Compare l'énergie mécanique au départ et à l'arrivée : la différence est ce qu'ont pris les frottements."},

 {id:"mc7", niveau:3, type:"qcm", enonce:"Deux billes de masses différentes sont lâchées de la même hauteur, sans frottement. Laquelle arrive le plus vite en bas ?",
  choix:["Les deux arrivent à la même vitesse","La plus lourde","La plus légère","Cela dépend de leur forme"], bonne:0,
  diag:["",
        "La bille lourde possède bien plus d'énergie potentielle — mais il lui en faut aussi davantage pour atteindre une vitesse donnée. Les deux effets se compensent exactement : la masse se simplifie dans le calcul.",
        "La bille légère a moins d'énergie potentielle, mais elle a aussi besoin de moins d'énergie pour aller vite. Là encore, tout se compense.",
        "La forme intervient dès qu'il y a des frottements avec l'air. Ici l'énoncé précise qu'il n'y en a pas."],
  corr:["**Ce que dit l'énoncé.** Deux billes de masses différentes, lâchées de la même hauteur, sans frottement. Laquelle arrive le plus vite ?",
        "**L'intuition à interroger.** On croit souvent que la plus lourde tombe plus vite. Le calcul va trancher.",
        "**Étape 1 — j'écris la conservation de l'énergie.** Au départ $E_m = m g h$ ; à l'arrivée $E_m = @f{1}{2} m v^2$. Sans frottement, les deux sont égales : $@f{1}{2} m v^2 = m g h$.",
        "**Étape 2 — je regarde où est la masse.** Elle apparaît **des deux côtés** de l'égalité. Je peux donc diviser les deux membres par $m$ : elle disparaît.",
        "**Étape 3 — ce qu'il reste.** $v^2 = 2 g h$, puis $v = @r{2gh}$. La vitesse finale ne dépend que de $g$ et de la hauteur.",
        "**Je conclus.** Les deux billes arrivent à la **même vitesse**. La bille lourde a plus d'énergie disponible, mais il lui en faut aussi davantage pour aller vite : les deux effets se compensent exactement. C'est l'expérience attribuée à Galilée."],
  indice:"Écris la conservation de l'énergie et regarde si la masse survit à la simplification."},

 {id:"mc8", niveau:3, type:"num", enonce:"Une caisse est tirée sur $10$ @u{m} par une force de $60$ @u{N} dans le sens du mouvement, contre un frottement de $25$ @u{N}. De combien varie son énergie cinétique, en @u{J} ?",
  rep:350, tol:5, unite:"J",
  diag:[{v:600, m:"Tu n'as compté que la force de traction. Le théorème de l'énergie cinétique fait intervenir la somme des travaux de **toutes** les forces, frottement compris."},
        {v:850, m:"Tu as additionné les deux travaux sans tenir compte du signe. Le frottement s'oppose au mouvement : son travail est **négatif**."},
        {v:250, m:"Tu as soustrait les forces avant de multiplier, mais avec une erreur de calcul : $60 - 25 = 35$, puis $35 × 10 = 350$."}],
  corr:["**Ce que dit l'énoncé.** Une force de traction de $60$ @u{N} dans le sens du mouvement, un frottement de $25$ @u{N}, sur $10$ @u{m}.",
        "**La loi à utiliser.** Le théorème de l'énergie cinétique : $ΔE_c = ΣW$, la variation d'énergie cinétique est la somme des travaux de **toutes** les forces.",
        "**Étape 1 — le travail de la traction.** Elle est dans le sens du déplacement, donc $α = 0°$ et le travail est positif : $W_1 = +60 × 10 = +600$ @u{J}.",
        "**Étape 2 — le travail du frottement.** Un frottement s'oppose toujours au mouvement, donc $α = 180°$ et $cos(180°) = -1$ : $W_2 = -25 × 10 = -250$ @u{J}.",
        "**Étape 3 — les autres forces.** Le poids et la réaction du sol sont perpendiculaires au déplacement horizontal : leur travail est nul, ils n'entrent pas dans le bilan.",
        "**Étape 4 — je somme.** $ΔE_c = 600 - 250 = 350$ @u{J}. Le résultat est positif : la caisse gagne de l'énergie, donc elle accélère."],
  indice:"Additionne les travaux en respectant leur signe : le frottement travaille négativement."},

{id:"mc9", niveau:1, type:"num", enonce:"Quelle est l'énergie cinétique d'un piéton de $70$ @u{kg} qui marche à $1{,}5$ @u{m/s} ? (arrondis à l'unité)",
  rep:79, tol:1, unite:"J",
  diag:[{v:105, m:"Tu as calculé $m × v$ : ni le carré de la vitesse, ni le facteur $@f{1}{2}$."},
        {v:158, m:"Tu as oublié le facteur $@f{1}{2}$. $E_c = 0{,}5 × 70 × 2{,}25$."},
        {v:52.5, m:"Tu as calculé $@f{1}{2} m v$ : il manque le carré sur la vitesse."}],
  corr:["**Ce que donne l'énoncé.** Une masse et une vitesse. Ce qu'on cherche : l'énergie que le piéton possède parce qu'il bouge.",
        "**La formule.** $E_c = @f{1}{2} m v^2$.",
        "**Étape 1 — le carré, en premier.** $1{,}5^2 = 2{,}25$. Le carré ne porte que sur la vitesse.",
        "**Étape 2 — je multiplie par la masse.** $70 × 2{,}25 = 157{,}5$.",
        "**Étape 3 — je prends la moitié.** $E_c = 0{,}5 × 157{,}5 ≈ 79$ @u{J}.",
        "**Je mets en perspective.** Une voiture de $1200$ @u{kg} à $20$ @u{m/s} emporte $240\u00a0000$ @u{J} : trois mille fois plus. Le carré de la vitesse explique presque tout cet écart."],
  indice:"Le carré de la vitesse d'abord, puis la masse, puis le facteur $@f{1}{2}$."},

 {id:"mc10", niveau:2, type:"num", enonce:"Un sac de $5{,}0$ @u{kg} descend de $3{,}0$ @u{m}. Quel est le travail de son poids, en @u{J} ? On prend $g = 9{,}81$ @u{N/kg}.",
  rep:147, tol:1, unite:"J",
  diag:[{v:-147, m:"Le signe est faux. Le sac **descend**, et le poids est dirigé vers le bas : force et déplacement vont dans le même sens, le travail est donc **moteur**, donc positif."},
        {v:15, m:"Tu as oublié $g$ : tu as calculé $m × h$. Le poids vaut $m × g$, et son travail $m × g × h$."},
        {v:0, m:"Le travail serait nul si le déplacement était horizontal. Ici le sac descend : le poids travaille pleinement."}],
  corr:["**Ce que dit l'énoncé.** Un sac qui **descend** de $3{,}0$ @u{m}. On cherche le travail de son poids.",
        "**La formule générale.** $W = F × d × cos(α)$, où $α$ est l'angle entre la force et le déplacement.",
        "**Étape 1 — la force.** Le poids vaut $P = m g = 5{,}0 × 9{,}81 = 49{,}05$ @u{N}, dirigé vers le bas.",
        "**Étape 2 — l'angle.** Le déplacement est vers le bas lui aussi : force et déplacement ont le même sens, donc $α = 0°$ et $cos(α) = 1$.",
        "**Étape 3 — je calcule.** $W = 49{,}05 × 3{,}0 × 1 ≈ 147$ @u{J}.",
        "**J'interprète le signe.** Positif : le travail est **moteur**, le poids apporte de l'énergie au sac, qui accélère en tombant. Si le sac **montait**, l'angle serait de $180°$ et le travail vaudrait $-147$ @u{J}."],
  indice:"Le sac descend et le poids tire vers le bas : quel est l'angle entre les deux ?"},

 {id:"mc11", niveau:2, type:"qcm", enonce:"Une voiture roule deux fois plus vite. Toutes choses égales par ailleurs, que devient sa distance de freinage ?",
  choix:["Elle est multipliée par 4","Elle est multipliée par 2","Elle ne change pas","Elle est multipliée par 8"], bonne:0,
  diag:["",
        "Ce serait le cas si l'énergie à dissiper dépendait simplement de la vitesse. Mais elle dépend de son **carré**.",
        "Rouler plus vite allonge évidemment le freinage. Et le facteur est plus grand qu'on ne le croit.",
        "8 correspondrait au cube de 2. L'énergie cinétique fait intervenir un carré, pas un cube."],
  corr:["**Ce qu'il faut dissiper au freinage.** Toute l'énergie cinétique de la voiture, $E_c = @f{1}{2} m v^2$.",
        "**Ce qui la dissipe.** Le travail des freins et des frottements : $W = -F × d$, où $d$ est la distance de freinage.",
        "**Le lien entre les deux.** Le théorème de l'énergie cinétique donne $F × d = @f{1}{2} m v^2$ : la distance est proportionnelle à $v^2$.",
        "**J'applique le facteur.** Si $v$ est doublée, $v^2$ est multipliée par $2^2 = 4$.",
        "**Je conclus.** La distance de freinage est multipliée par **4**, la force de freinage restant la même.",
        "**Ce que cela signifie sur la route.** Une voiture qui s'arrête en $15$ @u{m} à $50$ @u{km/h} met $60$ @u{m} à $100$ @u{km/h}. C'est le carré de la vitesse, et rien d'autre, qui rend les excès si dangereux."],
  indice:"L'énergie à dissiper dépend du carré de la vitesse. Et la distance de freinage suit cette énergie."},

 {id:"mc12", niveau:3, type:"num", enonce:"Une voiture de $1200$ @u{kg} roulant à $20$ @u{m/s} s'arrête en $40$ @u{m}. Quelle est la valeur de la force de freinage, supposée constante, en @u{N} ?",
  rep:6000, tol:50, unite:"N",
  diag:[{v:240000, m:"$240\u00a0000$ @u{J} est l'énergie cinétique à dissiper, pas la force. Il reste à la diviser par la distance de freinage."},
        {v:12000, m:"Tu as oublié le facteur $@f{1}{2}$ de l'énergie cinétique, ou divisé par $20$ au lieu de $40$."},
        {v:600, m:"Erreur d'un facteur 10 : $@f{240\u00a0000}{40} = 6000$, et non $600$."}],
  corr:["**Ce que dit l'énoncé.** Une voiture qui passe de $20$ @u{m/s} à l'arrêt sur $40$ @u{m}. On cherche la force qui l'a arrêtée.",
        "**L'outil.** Le théorème de l'énergie cinétique : $ΔE_c = ΣW$. Il relie une variation de vitesse à un travail, donc à une force et une distance.",
        "**Étape 1 — la variation d'énergie cinétique.** À l'arrivée $E_c = 0$ ; au départ $E_c = @f{1}{2} × 1200 × 20^2 = 0{,}5 × 1200 × 400 = 240\u00a0000$ @u{J}. Donc $ΔE_c = 0 - 240\u00a0000 = -240\u00a0000$ @u{J}.",
        "**Étape 2 — le travail des freins.** La force s'oppose au mouvement : $W = -F × d = -F × 40$.",
        "**Étape 3 — j'égale.** $-F × 40 = -240\u00a0000$, donc $F = @f{240\u00a0000}{40}$.",
        "**Je calcule et je vérifie.** $F = 6000$ @u{N}. C'est environ la moitié du poids de la voiture ($1200 × 9{,}81 ≈ 11\u00a0800$ @u{N}) : un ordre de grandeur réaliste pour un freinage énergique."],
  indice:"Toute l'énergie cinétique est dissipée sur $40$ @u{m} : écris $F × d = @f{1}{2} m v^2$."},

{id:"mc13", niveau:2, type:"num", unite:"J",
  enonce:"Le diagramme ci-dessous montre l'évolution des énergies d'une bille qui descend une piste sans frottement. Quelle est son énergie cinétique au point B ?",
  fig:{titre:"Document — bilan d'énergie le long de la piste", vue:[0,0,7,120], w:410, h:250,
       libre:true, grille:false, axes:false, objets:[
    {t:"axes", x0:0, y0:0, ax:"position", ay:"énergie (J)"},
    {t:"courbeXY", pts:[[0.6,100],[3,55],[5.6,10]], couleur:"ambre", points:true},
    {t:"courbeXY", pts:[[0.6,0],[3,45],[5.6,90]], couleur:"bleu", points:true},
    {t:"courbeXY", pts:[[0.6,100],[3,100],[5.6,100]], couleur:"vert", pointille:true},
    {t:"texte", x:6.3, y:8, txt:"Epp", couleur:"ambre", taille:12},
    {t:"texte", x:6.3, y:92, txt:"Ec", couleur:"bleu", taille:12},
    {t:"texte", x:6.3, y:104, txt:"Em", couleur:"vert", taille:12},
    {t:"seg", de:[3,0], a:[3,100], couleur:"line2", pointille:true},
    {t:"texte", x:3, y:-9, txt:"B", couleur:"ink", taille:13},
    {t:"texte", x:0.6, y:-9, txt:"A", couleur:"ink", taille:13},
    {t:"texte", x:5.6, y:-9, txt:"C", couleur:"ink", taille:13}
   ], note:"Trois courbes : l'énergie de réserve descend, celle du mouvement monte, leur somme ne bouge pas."},
  rep:45, tol:2,
  diag:[{v:55, m:"$55$ @u{J} est l'énergie **potentielle** au point B, la courbe ambre. L'énergie cinétique est la courbe bleue."},
        {v:100, m:"$100$ @u{J} est l'énergie **mécanique**, la droite verte du haut. Elle est la somme des deux autres, pas l'une d'elles."},
        {v:10, m:"$10$ @u{J} est l'énergie potentielle au point C, pas l'énergie cinétique en B."}],
  corr:["**Je commence par identifier les trois courbes.** L'ambre descend : c'est l'énergie potentielle, qui diminue à mesure que la bille perd de la hauteur.",
        "**La bleue monte** symétriquement : c'est l'énergie cinétique, qui augmente à mesure que la bille accélère.",
        "**La verte est horizontale** : c'est l'énergie mécanique, somme des deux. Elle ne bouge pas — la piste est sans frottement.",
        "**Je me place au point B** et je remonte à la courbe **bleue**, celle de l'énergie cinétique.",
        "**Je lis sur l'axe vertical.** $E_c = 45$ @u{J}.",
        "**Je vérifie avec la somme.** En B, $E_{pp} = 55$ @u{J} et $E_c = 45$ @u{J} : leur total fait bien $100$ @u{J}, la valeur constante de l'énergie mécanique. La lecture est cohérente."],
  indice:"Trois courbes : celle qui descend, celle qui monte, et leur somme. Laquelle représente le mouvement ?"},

 {id:"mc14", niveau:1, type:"num", enonce:"Un moteur fournit un travail de $60 000$ @u{J} en $30$ @u{s}. Quelle puissance développe-t-il, en @u{W} ?",
  rep:2000, tol:1, unite:"W",
  diag:[{v:1800000, m:"Tu as multiplié au lieu de diviser. La puissance est une énergie **par** seconde : $P = @f{W}{Δt}$."},
        {v:0.0005, m:"La division est à l'envers. C'est l'énergie qui va au numérateur : $@f{60 000}{30}$, et non l'inverse."},
        {v:2, m:"$2$ serait la puissance en kilowatts. La question demande des watts : $2$ @u{kW} $= 2000$ @u{W}."}],
  corr:["**Ce que dit l'énoncé.** Un travail de $60 000$ @u{J}, fourni en $30$ @u{s}. On cherche la puissance.",
        "**Ce qu'est une puissance.** Une énergie rapportée au temps : $P = @f{W}{Δt}$. Elle répond à la question « combien de joules chaque seconde ? ».",
        "**Étape 1 — je vérifie les unités.** L'énergie est déjà en joules, la durée déjà en secondes. Rien à convertir : c'est rare, profitons-en.",
        "**Étape 2 — je divise.** $P = @f{60 000}{30} = 2000$ @u{W}.",
        "**Étape 3 — j'écris l'unité.** $P = 2000$ @u{W}, soit $2{,}0$ @u{kW}.",
        "**Le contrôle.** $2000$ joules chaque seconde, pendant $30$ secondes, redonnent bien $60 000$ @u{J}. La multiplication à l'envers retombe sur l'énoncé : le résultat est juste."],
  indice:"Une puissance, c'est une énergie divisée par une durée en secondes."},

 {id:"mc15", niveau:2, type:"num", enonce:"Un cycliste développe une puissance de $240$ @u{W} en roulant à la vitesse constante de $8{,}0$ @u{m/s}. Quelle est la valeur de sa force de traction, en @u{N} ?",
  rep:30, tol:0.5, unite:"N",
  diag:[{v:1920, m:"Tu as multiplié $240$ par $8{,}0$. Mais c'est la **puissance** qui vaut $F × v$ : pour trouver $F$, il faut diviser."},
        {v:0.033, m:"La division est inversée : $F = @f{P}{v} = @f{240}{8{,}0}$, et non $@f{v}{P}$."},
        {v:24, m:"Attention au chiffre : $@f{240}{8} = 30$, et non $24$."}],
  corr:["**Ce que dit l'énoncé.** Une puissance $P = 240$ @u{W}, une vitesse $v = 8{,}0$ @u{m/s} constante. On cherche la force $F$.",
        "**L'outil.** Quand une force tire dans le sens du mouvement, $P = F × v$. C'est le raccourci qui évite de passer par la distance et la durée.",
        "**Étape 1 — j'isole la force.** De $P = F × v$ je tire $F = @f{P}{v}$.",
        "**Étape 2 — je remplace.** $F = @f{240}{8{,}0}$.",
        "**Étape 3 — je calcule.** $F = 30$ @u{N}.",
        "**Le contrôle, et ce qu'il faut retenir.** $30$ @u{N} à $8{,}0$ @u{m/s} redonnent bien $240$ @u{W}. Remarque ce que dit la formule : à puissance égale, s'il roulait deux fois plus vite, il ne pourrait plus pousser qu'avec $15$ @u{N}. C'est exactement pour cela qu'on change de vitesse en côte."],
  indice:"$P = F × v$. Ici c'est $F$ qui est inconnue : il faut isoler."},

 {id:"mc16", niveau:3, type:"num", enonce:"Une pompe monte $200$ @u{kg} d'eau à $10$ @u{m} de hauteur en $50$ @u{s}. Quelle puissance développe-t-elle, en @u{W} ? On prend $g = 10$ @u{N/kg}.",
  rep:400, tol:2, unite:"W",
  diag:[{v:20000, m:"$20 000$ @u{J} est le **travail** fourni, pas la puissance. Il reste à le diviser par les $50$ @u{s}."},
        {v:2000, m:"Tu as divisé par $10$ au lieu de $50$, ou oublié la hauteur. Reprends : $@f{20 000}{50}$."},
        {v:40, m:"Erreur d'un facteur 10 : $@f{20 000}{50} = 400$, et non $40$."}],
  corr:["**Ce que dit l'énoncé.** $200$ @u{kg} d'eau montés de $10$ @u{m} en $50$ @u{s}. On cherche une puissance, donc des watts.",
        "**La marche à suivre.** Une puissance ne se calcule jamais directement : il faut d'abord l'énergie, puis la durée.",
        "**Étape 1 — le travail contre le poids.** Monter une masse $m$ d'une hauteur $h$ demande $W = m g h = 200 × 10 × 10 = 20 000$ @u{J}.",
        "**Étape 2 — la durée.** $Δt = 50$ @u{s}, déjà en secondes.",
        "**Étape 3 — je divise.** $P = @f{W}{Δt} = @f{20 000}{50} = 400$ @u{W}.",
        "**Le contrôle.** $400$ @u{W}, c'est l'ordre de grandeur d'un gros cycliste : plausible pour une petite pompe de jardin. Et remarque que la puissance ne dit rien de la quantité d'eau montée — seulement de la vitesse à laquelle on la monte."],
  indice:"D'abord le travail contre le poids, $m g h$. Ensuite seulement, la division par la durée."}
]
}

]);
